  "Mover documentos a la papelera": "将文档移到废纸篓",
  "«{name}» dejará de aparecer. Podrás recuperarlo desde la administración de datos.": "「{name}」将不再显示。你可以从数据管理中恢复它。",
  "Los {n} documentos seleccionados dejarán de aparecer. Podrás recuperarlos desde la administración de datos.": "所选的{n}个文档将不再显示。你可以从数据管理中恢复它们。",
  "¿Eliminar también las ideas vinculadas?": "是否一并删除关联的观点？",
  "Se eliminarán las ideas que solo proceden de estos documentos, junto con sus embeddings, evidencia y conexiones. Las ideas compartidas con otras fuentes se conservarán.": "仅来自这些文档的观点将被删除，连同其嵌入、证据和连接。与其他来源共享的观点会保留。",
  "Eliminar ideas y embeddings": "删除观点和嵌入",
  "Conservar ideas": "保留观点",
  "Cancelar operación": "取消操作",
  "Eliminar idea": "删除观点",
  "Se eliminará «{name}» junto con su embedding, evidencia y conexiones. Esta acción no se puede deshacer.": "「{name}」将被删除，连同其嵌入、证据和连接。此操作无法撤销。",
  "Seleccionar o desplazar": "选择或滚动",
  "Editar o eliminar": "编辑或删除",
  "Suelta los archivos para añadirlos a esta sección": "拖放文件以将其添加到本节",
  "Se importarán como materiales en la selección actual.": "它们将作为材料导入当前选择中。",
  "No se pudo traducir este mensaje.": "无法翻译此消息。",
  "Analizando fragmento {current}/{total} con IA… ({seconds}s)": "正在使用AI分析片段 {current}/{total}…（{seconds}s）",
  "Analizando fragmento {current}/{total} con IA…": "正在使用AI分析片段 {current}/{total}…",
