  "{n} nuevas relaciones": "{n}条新关系",
  "{added} nuevas · {validated} validados · {scanned} escaneados": "{added}条新增 · {validated}条已验证 · {scanned}条已扫描",
  "Reintentando ({current}/{total})…": "正在重试（{current}/{total}）…",
  "Lecturas fundamentales": "基础阅读",
  "Base conceptual y dependencias intelectuales que conviene leer antes de avanzar.": "在推进之前宜先阅读的概念基础与思想脉络。",
  "Textos más útiles para cubrir o delimitar huecos detectados en el corpus.": "用于填补或界定语料库中所发现空白的最有用文本。",
