  "Finalizando claves de cita y cola de extracción…": "正在完成引注键和提取队列…",
  "Importación de Zotero completada y verificada.": "Zotero导入已完成并验证。",
  "Importación cancelada; el catálogo ya importado se conserva.": "导入已取消；已导入的目录会保留。",
  "No hay obras con análisis profundo para indexar.": "没有含深度分析的可索引文献。",
  "No hay obras disponibles para indexar.": "没有可索引的文献。",
  "La obra ya no existe.": "该文献已不存在。",
  "No se puede cambiar de bóveda con la cola de análisis activa. Pausa o termina los trabajos pendientes antes de cargar otra bóveda.": "分析队列处于活动状态时无法切换资料库。请在加载其他资料库之前暂停或完成待处理的任务。",
  "No se puede cambiar de bóveda mientras se están indexando embeddings de ideas.": "正在索引观点嵌入时无法切换资料库。",
  "No se puede cambiar de bóveda mientras se están indexando pasajes.": "正在索引片段时无法切换资料库。",
  "No se puede cambiar de bóveda mientras se descubren relaciones semánticas.": "正在发现语义关系时无法切换资料库。",
  "Bóveda no encontrada.": "未找到资料库。",
  "No se encontró la bóveda de origen de las claves API.": "未找到API密钥的来源资料库。",
