  "Limpiar terminadas": "清除已完成",
  "Limpiar tareas terminadas": "清除已完成任务",
  "Se ocultarán de la cola las tareas completadas, canceladas o fallidas. Se conservarán las tareas en curso, pendientes o en pausa y los documentos generados.": "已完成、已取消或失败的任务将从队列中隐藏。进行中、待处理或已暂停的任务以及生成的文档会保留。",
  "Extracción de texto": "文本提取",
  "Sin tareas ni colas en curso.": "没有进行中的任务或队列。",
  "Pausado": "已暂停",
  "Ruta optimizada por {strategy}: {shown} lecturas priorizadas de {total} obras, agrupadas en fases manejables.": "已按{strategy}优化路径：从{total}篇文献中优先选出{shown}篇阅读，并分组为可管理的阶段。",
  "Marcada como leída por la etiqueta de Zotero.": "由Zotero标签标记为已读。",
  "Pendiente de lectura.": "待阅读。",
