  "Aporta actualización reciente.": "提供近期更新。",
  "Coincide con las prioridades indicadas.": "符合所指示的优先事项。",
  "Conviene completar análisis antes de decidir su papel en el mapa.": "宜先完成分析，再决定其在地图中的角色。",
  "Notas rápidas": "快速笔记",
