  "Ahora puedes elegir a tu Nodi": "现在你可以选择你的 Nodi",
  "Nodi tiene un segundo aspecto: un orbe, más sobrio y discreto. Quédate con el de siempre o pruébalo.": "Nodi 有第二种外观：球体，更朴素低调。你可以保留熟悉的外观，也可以试试它。",
  "Podrás cambiarlo cuando quieras en Ajustes › Interfaz › Mascota Nodi.": "你可以随时在「设置 › 界面 › Nodi 吉祥物」中更改。",
  "Mantener siempre visible sobre otras apps": "始终保持在其他应用之上",
  "Trajes de Nodi según la bóveda": "Nodi 按资料库变化的服装",
  "Nodi lleva un pequeño accesorio según el modo de la bóveda (birrete, brote, gafas de estudio). Desactívalo para ver el Nodi normal en todas.": "Nodi 会根据资料库模式佩戴一个小配饰（学士帽、嫩芽、学习眼镜）。关闭它即可在所有资料库中看到普通的 Nodi。",
  "Abre a Nodi en una pequeña ventana flotante del escritorio, por encima del resto de aplicaciones (en los sistemas operativos que lo permiten). Puedes arrastrarla para moverla.": "在桌面小浮动窗口中打开 Nodi，使其位于其他应用之上（在允许此操作的操作系统上）。你可以拖动它来移动。",
