  "En vaults con datos personales, la IA se limitará inicialmente a modelos locales del usuario. También se valorará sustituir datos identificativos por placeholders que la IA no verá.": "在含个人数据的资料库中，AI最初将仅限于用户的本地模型。也会考虑将身份识别数据替换为AI无法看到的占位符。",
