  "Clases, cursos y materiales; la IA solo verá placeholders del alumnado.": "课堂、课程与材料；AI只会看到学生占位符。",
  "Vista previa navegable. Puedes crear el vault y consultar sus secciones, pero todavía no contienen funciones.": "可导航的预览。你可以创建该资料库并浏览其各个版块，但它们尚未包含功能。",
  "Este vault es una preview navegable: se creará normalmente, pero por ahora sus secciones son solo una muestra y no permiten realizar acciones.": "该资料库是可导航的预览：它会正常创建，但目前其版块仅为展示，无法执行操作。",
  "Este vault muestra la estructura prevista. Sus secciones todavía no permiten realizar acciones.": "该资料库展示的是计划结构。其版块目前仍无法执行操作。",
