  "El idioma de los prompts determina en qué idioma la IA genera ideas, temas, narrativa del tutor y borradores. Las citas textuales siempre conservan el idioma original de la fuente.": "提示词语言决定AI生成观点、主题、导师叙述和草稿时使用的语言。原文引注始终保留来源的原始语言。",
