  "El motor, el modelo y sus descargas se gestionan aquí. Los motores locales trabajan fuera del hilo de la interfaz y no envían el audio a terceros.": "引擎、模型及其下载都在此处管理。本地引擎在界面线程之外运行，不会将音频发送给第三方。",
  "Idioma del audio": "音频语言",
