  "El vocabulario del apunte y el diccionario personal se usan como contexto. Los audios se guardan solo en este dispositivo y se excluyen de sync y backups.": "笔记词汇表和个人词典会用作上下文。音频仅保存在此设备上，并会从同步和备份中排除。",
