  "Lo básico: sincronizar, escanear y moverte por el grafo.": "基础操作：同步、扫描并在图谱中导航。",
  "Ver de nuevo": "再次查看",
  "Tutorial avanzado de investigación": "高级研究教程",
  "El flujo completo: leer con criterio, comprender el corpus, encontrar tu aportación y escribir.": "完整流程：批判性阅读、理解语料库、找到你的贡献并写作。",
