  "storage no configurado": "未配置存储",
  "La sincronización puede funcionar, pero Nodus necesita un modelo predeterminado para extraer temas, ideas y evidencias.": "同步可以运行，但Nodus需要默认模型来提取主题、观点和证据。",
  "Sincroniza Zotero para crear el corpus": "同步Zotero以创建语料库",
  "Todavía no hay obras locales. Revisa las colecciones monitorizadas y ejecuta una sincronización para poblar la biblioteca.": "尚无本地文献。请检查监控的集合，并执行同步以填充文献库。",
  "Sincronizar ahora": "立即同步",
  "Completa el análisis ligero": "完成轻量分析",
  "El primer resultado visible del mapa depende de los temas extraídos a partir de título y resumen. Analiza temas antes de profundizar.": "图谱的首个可见结果取决于从标题和摘要中提取的主题。请先分析主题再深入。",
  "Analizar temas": "分析主题",
  "Ver grafo": "查看图谱",
  "Extrae ideas de las obras clave": "从关键文献中提取观点",
  "El grafo ya puede orientarte por temas; el siguiente salto de valor llega al analizar a fondo las obras leídas o seleccionadas.": "图谱已可按主题为你指引方向；下一个价值跃升来自对已读或所选文献的深度分析。",
  "Analizar ideas": "分析观点",
  "Indexa embeddings pendientes": "为待处理嵌入建立索引",
  "Hay ideas extraídas sin índice semántico. Indexarlas mejora la fusión, las relaciones y el descubrimiento de puentes.": "有已提取的观点尚无语义索引。为其建立索引可改善融合、关系和桥梁发现。",
  "Ver ideas": "查看观点",
  "Convierte el grafo en escritura": "将图谱转化为写作",
  "Ya hay suficientes ideas y fuentes para montar un estado de la cuestión, un marco teórico o una justificación de hueco con citas verificables.": "已有足够的观点和资料来撰写文献综述、理论框架或空白论证，并附可验证的引注。",
  "Abrir taller": "打开工作台",
  "Ver huecos": "查看空白",
  "Revisa huecos y contradicciones": "检查空白与矛盾",
  "El corpus ya tiene material interpretativo. El siguiente paso útil es convertir huecos y tensiones en una ruta de lectura o pregunta de investigación.": "语料库已有可解读的素材。下一步有用的做法是将空白与张力转化为阅读路径或研究问题。",
  "Explora el grafo con el Tutor": "与导师一起探索图谱",
  "El corpus está en buen estado para una lectura guiada. Abre el grafo o pregunta al asistente con el contexto completo.": "语料库状态良好，适合进行引导式阅读。请打开图谱，或带着完整上下文向助手提问。",
