  "Procesar todo": "全部处理",
  "Encadena temas, ideas, resumen, indexado (ideas y pasajes) y descubrimiento de relaciones.": "依次执行主题、观点、摘要、索引（观点与片段）及关系发现。",
  "Encadena temas, ideas, resumen, indexado (ideas y pasajes) y descubrimiento de relaciones para toda la biblioteca filtrada.": "对整个筛选后的文献库依次执行主题、观点、摘要、索引（观点与片段）及关系发现。",
  "Procesar todo encadena para las {n} obra(s) filtrada(s): temas, ideas, resumen, indexado (ideas y pasajes) y descubrimiento de relaciones. Es una operación larga que consume tokens del modelo seleccionado. ¿Continuar?": "全部处理将对筛选出的{n}篇文献依次执行：主题、观点、摘要、索引（观点与片段）及关系发现。这是一项耗时操作，会消耗所选模型的词元。是否继续？",
  "Procesado completo en cola para {n} obra(s). Verás el progreso en la cola.": "{n}篇文献的完整处理已加入队列。你可以在队列中查看进度。",
  "Después elige Temas, Ideas o Ambos.": "然后选择主题、观点或两者。",
  "{n} seleccionadas": "已选择{n}项",
  "Temas + ideas": "主题+观点",
  "Indexar": "建立索引",
  "Limpiar selección": "清除选择",
  "Reasignar temas": "重新分配主题",
  "Reconstruye los temas padre de toda la biblioteca con análisis ligero. Útil tras cambiar criterios temáticos.": "通过轻量分析重建整个文献库的父主题。更改主题标准后很有用。",
  "Reasignar": "重新分配",
  "Genera embeddings para las ideas que aún no los tienen. No regenera los existentes.": "为尚无嵌入的观点生成嵌入。不会重新生成已有的嵌入。",
  "Borra todos los embeddings y los regenera desde cero. Útil tras cambiar de modelo de embeddings.": "删除所有嵌入并从头重新生成。更换嵌入模型后很有用。",
  "Descubrir relaciones": "发现关系",
  "Usa embeddings e IA para validar puentes semánticos entre ideas que aún no están conectadas. El progreso se muestra en la cola.": "使用嵌入和AI验证尚未连接的观点之间的语义桥梁。进度会显示在队列中。",
  "Descubrir": "发现",
  "Filtrar por colección": "按集合筛选",
  "Sincroniza para poder filtrar por colección.": "同步后即可按集合筛选。",
  "Buscar colección…": "搜索集合…",
  "Combinar colecciones": "组合集合",
  "Aún no hay colecciones. Pulsa “Sincronizar” para leer la estructura de colecciones de Zotero.": "尚无集合。点击「同步」以读取Zotero的集合结构。",
  "No hay colecciones que coincidan.": "没有匹配的集合。",
  "Colecciones:": "集合：",
  "Buscar y fusionar duplicados": "查找并合并重复项",
  "Detecta obras repetidas (mismo DOI, o mismo título, año y autores) y te deja revisarlas y fusionarlas conservando una sola copia. La misma obra en varias colecciones de Zotero no se duplica.": "检测重复文献（相同DOI，或相同标题、年份和作者），让你检查并合并，只保留一份副本。同一文献存在于多个Zotero集合中不会被重复计算。",
  "Duplicados en la biblioteca": "文献库中的重复项",
