  "Esta idea aún no tiene conexiones con otras ideas.": "这条观点还没有与其他观点建立连接。",
  "Ver esta idea conectada": "查看这条已连接的观点",
  "No se pudo cargar el detalle de la idea.": "无法加载观点详情。",
  "Lectura:": "阅读：",
  "Preguntar al asistente sobre esta obra": "向助手询问这篇文献",
  "Analiza esta lectura dentro del corpus: ideas extraídas, temas, huecos, contradicciones y próximas lecturas relacionadas.": "在语料库中分析这篇阅读：已提取的观点、主题、空白、矛盾和相关的后续阅读。",
  "Reasignar temas vuelve a ejecutar el análisis ligero (título + abstract) sobre TODA la biblioteca para reconstruir los temas padre y agrupar las ideas existentes bajo ellos. Consume tokens del modelo seleccionado. ¿Continuar?": "重新分配主题会对整个文献库重新执行轻量分析（标题 + 摘要），以重建父主题并将现有观点归入其下。这会消耗所选模型的词元。是否继续？",
  "Reasignación de temas en cola para {n} obra(s). Verás el progreso en la cola.": "已为 {n} 篇文献排队主题重新分配。你可以在队列中查看进度。",
