  "contradicción sin resolver": "未解决的矛盾",
  "Huecos de investigación": "研究空白",
  "Agregados del corpus: trabajo futuro y limitaciones minados de las obras, y contradicciones sin reconciliar.": "语料库汇总：从文献中挖掘的未来工作和局限性，以及未调和的矛盾。",
