  "conf": "置信度",
  "Contradicción seleccionada": "已选矛盾",
  "Analiza esta contradicción del corpus. Resume las posiciones, evidencia y lecturas necesarias para decidir si es tensión real o diferencia de marco.": "分析语料库中的这一矛盾。总结各方立场、证据和所需阅读，以判断它是真实张力还是框架差异。",
