  "Sube obras antiguas, citadas internamente o usadas como dependencia conceptual.": "提升较早期文献的排位，这些文献被内部引用或用作概念依据。",
  "Ordena por actualidad sin ignorar relevancia temática.": "按时效排序，同时兼顾主题相关性。",
  "Da peso a autores relacionados por el grafo de ideas.": "提升通过观点图谱关联的作者的权重。",
