  "Temas principales": "主要主题",
  "Los temas principales son los grandes nodos que agrupan tus ideas en el grafo. Añade los tuyos para controlarlos manualmente; mientras estén bloqueados, los análisis solo usarán estos temas y no generarán otros nuevos.": "主要主题是图谱中聚合观点的较大节点。添加你自己的主题以手动控制它们；锁定期间，分析只会使用这些主题，不会生成新的主题。",
  "coge las ideas ya extraídas (afirmaciones, hallazgos…) y las vuelve a agrupar bajo estos temas con el modelo seleccionado, sin volver a leer los documentos ni re-extraer ideas.": "会获取已提取的观点（论断、发现…），并用所选模型将它们重新归入这些主题下，无需重新阅读文档或重新提取观点。",
