  "Una IA de contexto largo analiza todas tus ideas, temas y conexiones y traza un recorrido guiado. Avanza con las flechas y el Tutor te lo explica paso a paso sobre el propio grafo.": "长上下文 AI 会分析你的所有观点、主题和连接，并绘制一条引导路线。使用箭头前进，导师会在图谱上逐步为你讲解。",
