  "Desde un objetivo": "从目标出发",
  "Describe qué quieres repasar y el Tutor traza un recorrido a medida con las ideas y conexiones pertinentes.": "描述你想复习的内容，导师会结合相关观点和关系为你规划一条量身定制的路线。",
  "Ej.: Quiero repasar cómo se relaciona el concepto de identidad nacional con la literatura de viajes y dónde hay contradicciones.": "例如：我想复习民族认同这一概念与旅行文学的关系，以及其中存在哪些矛盾。",
