  "Ideas, huecos y contradicciones básicas.": "基本观点、空白和矛盾。",
  "Dame una síntesis crítica del corpus: ideas principales, contradicciones, huecos y próximos pasos.": "对语料库做一份批判性综述：主要观点、矛盾、空白和后续步骤。",
  "Preguntas abiertas, limitaciones y trabajo futuro.": "开放性问题、局限性和未来工作。",
  "Prioriza los huecos de investigación del corpus y propón cómo atacarlos con lecturas o análisis.": "优先梳理语料库的研究空白，并提出如何通过阅读或分析加以解决。",
  "Contradicciones": "矛盾",
