  "Informe eliminado.": "报告已删除。",
  "Escribe la pregunta o idea de investigación que quieres desarrollar. El informe la convierte en un texto de varias páginas, no en una respuesta corta.": "写下你想展开的研究问题或观点。报告会将其转化为多页文本，而不是简短回答。",
  "2. Ajusta el alcance": "2. 调整范围",
  "Elige la extensión objetivo y el número máximo de secciones. Menos secciones producen un texto más profundo; más secciones, uno más panorámico.": "选择目标篇幅和最大分节数。分节越少，文本越深入；分节越多，视野越全面。",
  "Nodus recorre todo el corpus indexado, planifica las secciones y redacta guiado por la cobertura, citando cada obra sin que tengas que seleccionarla.": "Nodus 会遍历整个已索引的语料库，规划分节，并在覆盖度引导下撰写，自动引用每篇文献，无需你手动选择。",
  "4. Revisa y exporta": "4. 检查并导出",
  "Abre las citas para comprobar cada fuente, guarda el informe para retomarlo y expórtalo a Markdown o PDF cuando esté listo.": "打开引注核对每个来源，保存报告以便日后继续，准备就绪后导出为 Markdown 或 PDF。",
  "Informe académico de varias páginas, guiado por cobertura y con todas las fuentes citadas.": "多页学术报告，以覆盖度为引导，并引用全部来源。",
  "Adaptativo (según corpus)": "自适应（依据语料库）",
  "Conciso (5–8 pág.)": "简洁（5–8 页）",
  "Estándar (9–14 pág.)": "标准（9–14 页）",
  "Exhaustivo (15–20 pág.)": "详尽（15–20 页）",
