  "Extensión:": "篇幅：",
  "Secciones:": "分节：",
  "Número máximo de secciones (menos secciones = mayor profundidad)": "最大分节数（分节越少 = 越深入）",
  "Secciones: Auto (IA decide)": "分节：自动（由 AI 决定）",
  "Bloque único · sin secciones": "单一整块 · 无分节",
  "Estructura del informe": "报告结构",
  "Una narración continua sin encabezados internos; conserva toda la recuperación y el análisis.": "一段连续的叙述，无内部标题；保留全部检索和分析。",
  "El esquema manual fija exactamente las partes y su orden.": "手动大纲会精确固定各部分及其顺序。",
  "La estructura organiza el informe, pero nunca limita la evidencia relevante.": "结构用于组织报告，但绝不限制相关证据。",
  "Secciones: Auto": "分节：自动",
