  "Generando informe…": "正在生成报告…",
  "No se pudo generar el informe.": "无法生成报告。",
  "Escribe la idea de investigación antes de generar el informe.": "生成报告前请先写下研究观点。",
  "Escribe la idea o pregunta de investigación. El informe la desarrollará por completo, citando todas las obras del corpus.": "写下研究观点或问题。报告会将其完整展开，并引用语料库中的所有文献。",
  "Cobertura del corpus completo": "全语料库覆盖",
  "Sin selección manual: el informe elige y cita las fuentes por ti.": "无需手动选择：报告会替你挑选并引用来源。",
  "Puedes cambiar de sección: el informe seguirá en segundo plano y recuperarás este progreso al volver.": "你可以切换分节：报告将在后台继续，返回时可恢复此进度。",
  "Informe generado: {s} secciones · ~{p} páginas · {i} ideas citadas.": "报告已生成：{s} 个分节 · 约 {p} 页 · 引用 {i} 个观点。",
  "Informe generado y guardado: {s} secciones · ~{p} páginas · {i} ideas citadas.": "报告已生成并保存：{s} 个分节 · 约 {p} 页 · 引用 {i} 个观点。",
  "Informe generado, pero no se pudo guardar automáticamente: {error}": "报告已生成，但无法自动保存：{error}",
  "El informe está listo y puedes guardarlo manualmente.": "报告已就绪，你可以手动保存。",
  "El informe aparecerá aquí. Escribe tu idea de investigación y pulsa «Generar informe».": "报告将显示在这里。写下你的研究观点，然后点击「生成报告」。",
  "Planifica, redacta sección a sección guiado por la cobertura del corpus y ensambla un informe académico de 5–20 páginas con todas las fuentes citadas.": "在语料库覆盖度的引导下规划并逐节撰写，最终汇编成一份 5–20 页、引用全部来源的学术报告。",
