  "Sin matriz todavía.": "尚无矩阵。",
  "abrir fuente": "打开来源",
  "1. Delimita": "1. 明确范围",
  "Escribe el apartado que quieres construir: pregunta, capítulo, debate, hueco o marco teórico. Cuanto más concreto sea el objetivo, mejor se ordena la mesa.": "写下你想构建的章节：问题、章、讨论、空白或理论框架。目标越具体，工作台组织得越好。",
  "2. Monta la mesa": "2. 搭建工作台",
  "Pulsa Preparar mesa y revisa ideas, temas, huecos, contradicciones, obras y rutas. Usa Todas las ideas cuando quieras una revisión amplia del corpus encontrado.": "点击「准备工作台」，查看观点、主题、空白、矛盾、文献和路线。想要广泛审视已找到的语料库时，使用「所有观点」。",
  "3. Decide el foco": "3. 确定重点",
  "Selecciona todo para explorar, vacía para empezar de cero o ajusta cada pestaña. La matriz final te dirá qué papel cumple cada material en el argumento.": "全选以探索，清空以从零开始，或逐一调整每个标签页。最终矩阵会告诉你每份材料在论证中的作用。",
  "4. Convierte en texto": "4. 转化为文本",
  "Genera el borrador, abre las citas para verificar fuentes, guárdalo si quieres retomarlo y exporta Markdown cuando el hilo argumental ya tenga sentido para tu manuscrito.": "生成草稿，打开引注核对来源，如需日后继续可先保存，当论证脉络适合你的手稿时导出 Markdown。",
