  "Describe una idea para encontrar pasajes, ideas y obras con significado parecido.": "描述一个观点，以查找含义相近的片段、观点和文献。",
  "Escribe al menos dos caracteres para buscar en todo el espacio de trabajo.": "输入至少两个字符即可搜索整个工作区。",
