  "Próximas acciones": "后续操作",
  "Todo en orden: no hay análisis, indexado ni recuperación pendientes.": "一切正常：没有待处理的分析、索引或恢复任务。",
  "Analiza a fondo {n} obra(s) prioritaria(s)": "深度分析 {n} 篇优先文献",
  "Marcadas como leídas o seleccionadas, pero todavía sin ideas extraídas.": "已标记为已读或已选中，但尚未提取观点。",
  "Profundiza {n} obra(s) con solo análisis ligero": "深入分析 {n} 篇仅有轻度分析的文献",
  "Tienen temas pero aún no ideas; son las candidatas naturales al análisis profundo.": "它们已有主题但尚无观点，是深度分析的天然候选。",
  "Indexa {n} idea(s) sin embedding": "为 {n} 个无嵌入的观点建立索引",
  "La búsqueda por significado, la fusión y los puentes dependen del índice semántico.": "语义搜索、融合与桥接都依赖语义索引。",
  "Indexa pasajes de {n} obra(s) con texto": "为 {n} 篇有文本的文献索引片段",
  "Sin pasajes no hay búsqueda semántica de evidencia ni citas a nivel de fragmento.": "没有片段，就无法进行证据的语义搜索，也无法实现片段级引用。",
  "Recupera el texto de {n} obra(s)": "恢复 {n} 篇文献的文本",
  "No se pudo extraer texto, pero hay vía de recuperación (re-escanear, OCR o descargar por DOI).": "无法提取文本，但有恢复途径（重新扫描、OCR 或按 DOI 下载）。",
  "Flujo guiado de tesis": "论文引导流程",
  "Flujo guiado de artículo": "文章引导流程",
  "Flujo guiado de manuscrito": "手稿引导流程",
  "Proyecto listo para revisar, exportar o cerrar.": "项目已可审阅、导出或关闭。",
  "Brief y pregunta": "简报与问题",
  "Objetivo, alcance y criterio de lectura definidos.": "已定义目标、范围和阅读标准。",
  "Pregunta y cobertura": "问题与覆盖范围",
  "Pregunta principal conectada con la cobertura del corpus.": "主要问题与语料库覆盖范围相关联。",
  "Corpus y materiales": "语料库与材料",
  "Obras, ideas, notas, huecos o borradores listos para integrarse.": "可整合的文献、观点、笔记、空白或草稿。",
  "Debates, huecos y borradores organizados antes de intervenir el texto.": "在修改文本之前，先整理好讨论、空白与草稿。",
  "Manuscrito": "手稿",
  "Capítulo o artículo importado como texto editable y versionado.": "以可编辑、可版本化的文本导入的章节或文章。",
  "Revisión y salida": "审阅与输出",
  "Relaciones, sugerencias verificables y exportación final.": "关系、可验证建议与最终导出。",
  "Marcar cobertura": "标记覆盖范围",
  "Preparar materiales": "准备材料",
  "Preparar estructura": "准备结构",
  "Subir capítulo": "上传章节",
  "Revisar capítulo": "审阅章节",
  "Objetivo, alcance, pregunta principal y criterio de selección": "目标、范围、主要问题与选择标准",
  "Brief actualizado. El flujo guiado ya usa este objetivo.": "简报已更新。引导流程现已使用此目标。",
  "Cobertura marcada como en curso.": "覆盖范围已标记为进行中。",
  "Materiales preparados para el estado de la cuestión.": "已为文献综述准备好材料。",
  "Estructura argumental preparada.": "论证结构已准备就绪。",
  "No se encontraron nuevas sugerencias verificables para este capítulo.": "未发现此章节新的可验证建议。",
  "Define el objetivo, el alcance, la pregunta principal y el criterio de selección de fuentes. Este texto aparece en la cabecera del proyecto, se envía como contexto a la IA al generar sugerencias y se incluye en la exportación.": "定义目标、范围、主要问题与资料来源选择标准。此文本会显示在项目页眉中，在生成建议时作为上下文发送给 AI，并包含在导出内容中。",
  "Vincula tu pregunta de investigación con el corpus: indica qué áreas ya están cubiertas y qué falta por explorar. Marcar este paso como en curso activa la sección de cobertura en el proyecto.": "将你的研究问题与语料库关联起来：说明哪些领域已被覆盖、哪些尚待探索。将此步骤标记为进行中会激活项目中的覆盖范围部分。",
  "Añade obras, ideas, notas, huecos, debates y borradores al proyecto. Estos materiales son los que la IA usará para proponer inserciones con citas verificables en el manuscrito.": "向项目添加文献、观点、笔记、空白、讨论与草稿。AI 将使用这些材料，在手稿中提出带有可验证引用的插入建议。",
  "Organiza los debates, huecos y borradores que estructurarán el argumento antes de redactar los capítulos. Puedes activar cada bloque por separado para marcar que está listo para usarse.": "在撰写各章节之前，整理好将构成论证的讨论、空白与草稿。你可以单独启用每个模块，以标记其可供使用。",
  "Importa un capítulo o artículo como texto editable. Nodus lo versiona automáticamente y permite aplicar sugerencias sobre el borrador.": "将章节或文章导入为可编辑文本。Nodus 会自动为其建立版本，并允许在草稿上应用建议。",
  "Genera sugerencias verificables contra el corpus y revisa las citas del manuscrito antes de exportar o cerrar el proyecto.": "根据语料库生成可验证建议，并在导出或关闭项目之前审阅手稿中的引用。",
  "Guardando brief...": "正在保存简报…",
  "Actualizando sección...": "正在更新章节…",
