  "El grafo no se pudo renderizar": "无法渲染图谱",
  "Carga un corpus de demostración de seis obras sobre la ciencia del aprendizaje. Podrás recorrer el grafo, ideas, debates, huecos y notas sin conectar Zotero ni configurar una clave de IA.": "加载一个包含六篇学习科学相关文献的演示语料库。无需连接 Zotero 或配置 AI 密钥，即可浏览图谱、观点、争论、空白和笔记。",
  "Cargar demo": "加载演示",
  "Explora con datos de ejemplo": "使用示例数据探索",
  "Prueba sin configurar nada": "无需任何配置即可试用",
  "Crea resúmenes de orientación independientes a partir de ideas, evidencia, temas y abstract. No son evidencia citable.": "基于观点、证据、主题和原文摘要创建独立的定位摘要。它们不是可引用的证据。",
  "El análisis profundo solo usó el abstract, no el texto completo (el PDF/EPUB no estaba disponible al analizar). Reanaliza cuando esté en Zotero.": "深度分析仅使用了原文摘要，未使用全文（分析时 PDF/EPUB 不可用）。待其加入 Zotero 后重新分析。",
  "El texto o el modelo de embeddings cambió.": "文本或嵌入模型已更改。",
  "Las ideas pertenecen a la versión anterior del texto. Vuelve a analizarlas para usar el texto actual.": "这些观点属于文本的旧版本。请重新分析以使用当前文本。",
  "El texto cambió; vuelve a indexar sus fragmentos.": "文本已更改；请重新索引其片段。",
  "Los fragmentos se indexaron con otro modelo de embeddings.": "这些片段是使用其他嵌入模型索引的。",
  "El texto y el modelo de embeddings cambiaron.": "文本和嵌入模型均已更改。",
  "Algunos fragmentos no tienen un embedding válido.": "部分片段没有有效的嵌入。",
  "Generar resúmenes faltantes": "生成缺失的摘要",
  "Indexa fragmentos de texto completo en las obras que faltan o están obsoletas. No requiere análisis de ideas; el texto se mantiene como evidencia citable.": "为缺失或过期的文献索引全文片段。无需分析观点；文本仍作为可引用的证据。",
  "Indexar pasajes": "索引片段",
  "Indexar pasajes de esta obra": "索引此文献的片段",
  "Indexar todo": "全部索引",
  "No hay obras «solo abstract» para reanalizar.": "没有需要重新分析的「仅原文摘要」文献。",
  "obsoleto": "已过期",
  "Pasajes (texto completo)": "片段（全文）",
  "Procesar faltantes": "处理缺失项",
  "Procesar pasajes faltantes": "处理缺失片段",
  "Reanálisis en cola para {n} obra(s) «solo abstract». Verás el progreso en la cola.": "{n} 篇「仅原文摘要」文献已加入重新分析队列。你将在队列中看到进度。",
  "Reanaliza las obras que solo se analizaron con el abstract (el PDF/EPUB no estaba disponible al analizarlas). Las que ya tengan el texto disponible en Zotero recuperarán el análisis completo; el resto se omiten sin coste. ¿Continuar?": "重新分析仅使用原文摘要分析的文献（分析时 PDF/EPUB 不可用）。已在 Zotero 中有可用文本的文献将恢复完整分析；其余文献将被跳过，不产生费用。是否继续？",
  "Reanalizar": "重新分析",
  "Reanalizar «solo abstract»": "重新分析「仅原文摘要」",
  "Recorre toda la biblioteca y actualiza solo los índices que hayan cambiado. Los ya actuales se omiten.": "遍历整个文献库，仅更新已更改的索引。已是最新的索引将被跳过。",
  "resumen": "摘要",
  "solo abstract": "仅原文摘要",
  "Vuelve a analizar las obras cuyo análisis profundo solo usó el abstract porque el PDF/EPUB no estaba disponible. Las que ya tengan el texto recuperan el análisis completo; el resto se omiten sin coste.": "重新分析那些因 PDF/EPUB 不可用而仅使用原文摘要进行深度分析的文献。已有文本的文献将恢复完整分析；其余文献将被跳过，不产生费用。",
  "Añade citas textuales con su página o rango de páginas.": "添加原文引文及其页码或页码范围。",
