  "texto completo": "全文",
  "Reinicializar el grafo": "重置图谱",
  "Reinicializar el grafo borrará TODAS las ideas, temas, conexiones, autores y huecos, y dejará cada obra sin analizar. Tu biblioteca de Zotero y tus ajustes se conservan. Esta acción no se puede deshacer.": "重置图谱将删除所有观点、主题、连接、作者和空白，并将每篇文献恢复为未分析状态。你的 Zotero 文献库和设置会保留。此操作无法撤销。",
  "Eliminar borrador": "删除草稿",
  "Eliminar informe": "删除报告",
  "Procesar toda la biblioteca": "处理整个文献库",
  "Escribir": "写作",
