  "Actualizar (sincronizar Zotero)": "更新（同步 Zotero）",
  "Algo ha fallado en esta sección": "此章节出现问题",
  "Se produjo un error inesperado al mostrar esta vista. El resto de la app sigue funcionando: reinténtalo o cambia de sección.": "显示此视图时发生意外错误。应用的其他部分仍可正常使用：请重试或切换章节。",
  "Recargar Nodus": "重新加载 Nodus",
  "Domina un tema de tu corpus en una tarde.": "用一个下午精通你语料库中的某个主题。",
  "Una ruta completamente guiada: panorama, estaciones con citas literales del texto completo, contrastes entre autores, fronteras del corpus y examen final. Todo queda grabado para retomarlo cuando quieras.": "一条完全引导式的路线：全景、包含全文原文引用的站点、作者之间的对比、语料库的边界以及最终测验。所有内容都会被记录，方便你随时继续。",
  "¿De qué quieres hacerte experto? P. ej.: uso franquista de las fiestas y tradiciones": "你想在什么领域成为专家？例如：佛朗哥时期对节庆和传统的利用",
  "Exprés": "快速",
  "Una tarde": "一个下午",
  "~6 paradas": "~6 个站点",
  "~12 paradas": "~12 个站点",
  "~20 paradas": "~20 个站点",
  "Cartografiando…": "正在绘制…",
  "Explorar el territorio": "探索领域",
  "Las preguntas siempre se pueden saltar durante la sesión": "在会话过程中随时可以跳过问题",
  "Tus inmersiones": "你的沉浸式学习",
  "Aún no hay inmersiones guardadas. Cada recorrido que generes quedará aquí, con su progreso y tus respuestas, listo para retomarlo.": "还没有已保存的沉浸式学习。你生成的每条路线都会保存在这里，连同其进度和你的回答，随时可以继续。",
  "{n} estaciones": "{n} 个站点",
  "Eliminar inmersión": "删除沉浸式学习",
  "¿Eliminar esta inmersión y todo su progreso? Esta acción no se puede deshacer.": "要删除这次沉浸式学习及其全部进度吗？此操作无法撤销。",
  "Esto es lo que tu corpus sabe del tema. Sin IA todavía: solo embeddings y grafo.": "这是你的语料库对该主题所了解的内容。尚未使用 AI：只有嵌入和图谱。",
  "No hay material suficiente para una inmersión": "没有足够的材料进行沉浸式学习",
