  "Comenzar inmersión": "开始沉浸式学习",
  "obras": "文献",
  "autores": "作者",
  "Ruta de ~{n} estaciones guiadas: panorama, contrastes, fronteras y examen final{quiz}. La IA ajusta el número según lo que el tema pida.": "包含约 {n} 个引导站点的路线：全景、对比、边界和最终测验{quiz}。AI 会根据主题的需要调整数量。",
