  "Ideas más fuertes": "最有力的观点",
  "No hay suficientes ideas conectadas para dibujar el territorio.": "没有足够多的关联观点来绘制该领域。",
  "Generando tu inmersión…": "正在生成你的沉浸式学习…",
  "Cada respuesta de la IA se guarda: este recorrido será tuyo para siempre y podrás retomarlo sin regenerar nada.": "AI 的每个回答都会被保存：这条路线将永远属于你，你可以随时继续，无需重新生成任何内容。",
  "Cada parte generada por la IA se guarda: podrás retomar el recorrido sin regenerarlo. Las respuestas de test y texto se limpian al reiniciar.": "AI 生成的每个部分都会被保存：你可以继续该路线而无需重新生成。测验和文本回答会在重新开始时清空。",
  "Puedes cambiar de sección: la generación seguirá en segundo plano y este progreso reaparecerá cuando vuelvas.": "你可以切换章节：生成将在后台继续进行，返回时此进度会重新显示。",
