  "p. {p}": "第 {p} 页",
  "Quién dice qué, frente a frente": "谁说了什么，面对面",
  "La matriz que distingue a un experto: cada autor frente a cada sub-pregunta. Las celdas vacías también informan — ese autor no se pronuncia ahí.": "区分专家与否的矩阵：每位作者面对每个子问题。空白单元格同样传递信息——该作者在此没有表态。",
  "No hay suficientes autores con posiciones diferenciadas en este tema.": "该主题下没有足够多立场各异的作者。",
  "Sub-pregunta": "子问题",
  "Lo que tu corpus no sabe (todavía)": "你的语料库（还）不知道的内容",
  "Conocer los límites es parte de la maestría: aquí terminan tus fuentes y empieza el trabajo futuro.": "了解边界是专业能力的一部分：你的资料到此为止，未来的工作由此开始。",
  "No se detectaron huecos relevantes para este tema. Buen síntoma.": "未检测到该主题的相关空白。这是个好迹象。",
  "Inmersión completada": "沉浸式学习已完成",
  "Demuestra que eres experto": "证明你是专家",
  "Cubre todas las estaciones. Cada pregunta es opcional: respóndelas para medirte o sáltalas sin más.": "涵盖所有站点。每个问题都是可选的：可以回答以检验自己，也可以直接跳过。",
  "Sesión sin preguntas: cierra con la explicación final y da la inmersión por completada.": "无问题会话：以最终讲解收尾，并将沉浸式学习标记为已完成。",
  "Dominio del corpus verificado": "语料库掌握情况已验证",
  "{s} estaciones · {q} preguntas respondidas{score}": "{s} 个站点 · 已回答 {q} 个问题{score}",
  "nota media": "平均分",
  "Guardar dossier en notas": "将档案保存到笔记",
  "Volver al inicio": "返回开头",
  "El cierre Feynman": "费曼收尾",
  "Hazlo en voz alta o por escrito. Si te atascas en un punto, vuelve a su estación — para eso están las flechas.": "可以口头或书面完成。如果某处卡住，就回到对应的站点——箭头正是为此而设。",
  "Terminar inmersión": "结束沉浸式学习",
  "Sólida": "扎实",
  "Floja": "薄弱",
  "Responde con tus palabras: tesis, autores y evidencia…": "用你自己的话回答：论点、作者和证据…",
  "Evaluar con IA": "用 AI 评估",
  "Evaluando…": "正在评估…",
  "Opcional: puedes seguir sin responder.": "可选：你可以不作答继续。",
  "Te faltó:": "你遗漏了：",
  "Vocabulario": "词汇",
  "Citas literales": "原文引用",
  "Posiciones": "立场",
  "Cierre Feynman": "费曼收尾",
  "Apertura": "开场",
  "Cierre": "收尾",
