  "La ruta de hoy": "今日路线",
  "{n} citas": "{n} 条引用",
  "{n} citas literales": "{n} 条原文引用",
  "{n} voces": "{n} 个声音",
  "~{n} min": "约 {n} 分钟",
  "Siguiente:": "下一项：",
  "Estación {n} de {m}": "站点 {n}，共 {m}",
  "Por qué importa": "为何重要",
  "La lección": "课程",
  "Lectura guiada: citas que un experto conoce de memoria": "引导式阅读：专家烂熟于心的引用",
  "Cómo leer este pasaje": "如何阅读这段片段",
  "Para retener": "便于记忆",
  "Lectura guiada": "引导式阅读",
  "← → · progreso guardado": "← → · 进度已保存",
  "Voces de esta estación": "本站点的声音",
  "Obras sobre la mesa": "桌上的文献",
  "Esta inmersión": "这次沉浸式学习",
  "estaciones": "站点",
  "citas": "引用",
  "preguntas": "问题",
  "El territorio completo": "完整领域",
  "Falta la clave del proveedor de IA: configúrala en Ajustes": "缺少 AI 提供商的密钥：请在设置中配置",
  "Profundiza: informe Deep Research del tema": "深入探索：该主题的 Deep Research 报告",
  "Ahora que dominas el tema, genera el informe académico de varias páginas con todas las fuentes citadas. Se guarda en Deep Research y podrás exportarlo o citarlo en tu escritura.": "既然你已掌握该主题，现在可以生成引用全部来源的多页学术报告。它会保存在 Deep Research 中，你可以导出或在写作中引用。",
  "Puedes cambiar de sección: el informe seguirá generándose y mostrará el progreso al volver.": "你可以切换章节：报告将继续生成，返回时会显示进度。",
  "Dossier guardado: «{t}» · {s} secciones · ~{p} páginas. Lo tienes en Deep Research → informes guardados.": "档案已保存：「{t}」· {s} 个章节 · 约 {p} 页。可在 Deep Research → 已保存的报告 中找到。",
  "Generar de nuevo": "重新生成",
  "Seleccionar modelo": "选择模型",
  "Usar modelo de síntesis": "使用综合模型",
  "Modelo inicial para las tareas de IA ({n} disponibles)": "AI 任务的初始模型（{n} 个可用）",
  "Modelos favoritos para los selectores independientes": "用于独立选择器的收藏模型",
  "Los modelos de análisis se configuran en Ajustes.": "分析模型在设置中配置。",
  "Modelos de análisis: Ajustes": "分析模型：设置",
  "coge las ideas ya extraídas (afirmaciones, hallazgos…) y las vuelve a agrupar bajo estos temas con los modelos configurados en Ajustes, sin volver a leer los documentos ni re-extraer ideas.": "提取已提取的观点（论断、发现……），并使用设置中配置的模型将这些观点重新归入这些主题，无需重新阅读文档或重新提取观点。",
  "Cada tarea usa su propio modelo. Los escaneos, resúmenes, fusión y embeddings obedecen estos ajustes; Chat, Deep Research, Inmersión y las demás herramientas conservan el modelo elegido dentro de su propia sección.": "每项任务使用各自的模型。扫描、摘要、合并和嵌入都遵循这些设置；Chat、Deep Research、沉浸式学习及其他工具则保留在其各自章节内选择的模型。",
  "Modelo de síntesis general (fallback inicial para herramientas con selector propio)": "通用综合模型（带有独立选择器的工具的初始后备模型）",
  "modelos por tarea": "按任务划分的模型",
  "Extracción: {provider}": "提取：{provider}",
  "Síntesis: {provider}": "综合：{provider}",
  "Configura los modelos de IA": "配置 AI 模型",
  "La sincronización puede funcionar, pero Nodus necesita modelos separados de extracción y síntesis para analizar el corpus.": "同步可以正常工作，但 Nodus 需要独立的提取模型和综合模型来分析语料库。",
  "Generación de imágenes": "图像生成",
  "Configuración independiente para las imágenes decorativas opcionales. OpenAI usa su API oficial de imágenes y reutiliza la clave de OpenAI; Google reutiliza la clave de Gemini.": "用于可选装饰性图像的独立设置。OpenAI 使用其官方图像 API，并复用 OpenAI 密钥；Google 复用 Gemini 密钥。",
  "Actualizar modelos": "更新模型",
  "Estilo predeterminado": "默认样式",
  "Selección actual": "当前选择",
  "Buscar por proveedor, nombre o identificador…": "按提供商、名称或标识符搜索…",
  "Proveedor y nombre": "提供商和名称",
  "Orden alfabético": "字母顺序",
  "Precio por imagen: menor a mayor (por proveedor)": "每张图像价格：从低到高（按提供商）",
  "Precio por imagen: mayor a menor (por proveedor)": "每张图像价格：从高到低（按提供商）",
  "Como los proveedores publican tamaños y métricas diferentes, la ordenación por precio se aplica por separado dentro de cada proveedor. Los modelos sin precio directo quedan al final; no se estiman costes.": "由于各提供商公布的尺寸和指标不同，价格排序在每个提供商内部单独应用。没有直接价格的模型排在最后；不会估算费用。",
  "Consultando catálogos oficiales…": "正在查询官方目录…",
  "Entrada": "输入",
  "Salida": "输出",
  "No hay modelos compatibles que coincidan.": "没有匹配的兼容模型。",
  "Ver catálogo de OpenRouter": "查看 OpenRouter 目录",
  "{n} modelos compatibles con salida de imagen": "{n} 个支持图像输出的兼容模型",
  "Ilustración antigua de libro": "古籍插画",
