  "Pintura al óleo": "油画",
  "Imagen decorativa": "装饰图片",
  "Se genera una sola vez después de guardar la inmersión": "保存沉浸后仅生成一次",
  "La imagen se genera una sola vez después de guardar el informe": "保存报告后仅生成一次图片",
  "Estilo": "风格",
  "Generar imagen": "生成图片",
  "Generando imagen decorativa en segundo plano…": "正在后台生成装饰图片…",
  "Regenerar imagen": "重新生成图片",
  "Se realizará una nueva generación y puede producir un coste adicional. ¿Continuar?": "将重新生成，可能产生额外费用。是否继续？",
  "Eliminar imagen": "删除图片",
  "La imagen se eliminará del almacenamiento local. El contenido principal no cambiará.": "图片将从本地存储中删除。主要内容不会改变。",
  "Generar inmersión": "生成沉浸",
  "Tu inmersión está lista": "你的沉浸已准备好",
  "Puedes empezar ya: la imagen nunca bloquea el contenido.": "你可以立即开始：图片不会阻塞内容。",
  "Diseño de la imagen": "图片设计",
  "Ajusta el estilo y la escena. Se genera una imagen nueva.": "调整风格和场景。将生成一张新图片。",
  "Descripción de la escena": "场景描述",
  "Describe la escena que quieres ver. Si lo dejas vacío, se deduce del contenido.": "描述你想看到的场景。如果留空，将从内容中推断。",
  "El estilo y las protecciones de «sin texto» se aplican automáticamente al generar.": "生成时会自动应用风格和「无文字」保护。",
  "La imagen aparecerá aquí una vez generada.": "图片生成后将显示在这里。",
  "Añadir imagen decorativa": "添加装饰图片",
  "La imagen no pudo generarse.": "图片生成失败。",
  "Al generar se solicita una imagen nueva, que puede tener un coste adicional.": "生成时会请求一张新图片，可能产生额外费用。",
  "Subir mi imagen": "上传我的图片",
  "Volver a la imagen anterior": "返回上一张图片",
  "Tu imagen se comprime automáticamente para no sobrecargar el almacenamiento.": "你的图片会自动压缩，以免占用过多存储空间。",
  "No se pudo leer el archivo de imagen.": "无法读取图片文件。",
  "No se pudo procesar la imagen.": "无法处理图片。",
  "No se pudo comprimir la imagen.": "无法压缩图片。",
  "El archivo de imagen está vacío.": "图片文件为空。",
  "El elemento ya no está disponible.": "该条目已不可用。",
  "Abrir nota": "打开笔记",
  "Abrir en Huecos": "在「空白」中打开",
  "Localizar en el grafo": "在图谱中定位",
  "Cargando detalle…": "正在加载详情…",
  "note": "笔记",
  "work": "文献",
  "gap": "空白",
  "theme": "主题",
  "author": "作者",
  "passage": "片段",
  "Tipo de obra": "文献类型",
  "Clave de Zotero": "Zotero 键",
  "Fuente de texto": "文本来源",
  "Creada": "已创建",
  "Caracteres": "字符数",
