  "Afiliación": "所属机构",
  "Identidad canónica": "规范身份",
  "Actualizada": "已更新",
  "(local)": "（本地）",
  "Cargado en memoria": "已加载到内存",
  "Ollama debe estar en marcha y los modelos descargados con \"ollama pull\". No requiere clave.": "Ollama 必须正在运行，并通过 \"ollama pull\" 下载模型。无需密钥。",
  "Activa el servidor local en LM Studio (Developer → Start Server) y carga al menos un modelo. No requiere clave.": "在 LM Studio 中启动本地服务器（Developer → Start Server）并加载至少一个模型。无需密钥。",
  "Dirección del servidor (IP y puerto)": "服务器地址（IP 和端口）",
  "Probando…": "正在测试…",
  "Probar conexión": "测试连接",
  "Conectado{version} · {n} modelos disponibles": "已连接{version} · {n} 个模型可用",
  "Sin conexión: {msg}": "未连接：{msg}",
  "•••••••• token guardado (opcional)": "•••••••• 令牌已保存（可选）",
  "token de acceso (opcional)": "访问令牌（可选）",
  "El servidor no reporta modelos. Descarga o carga uno primero.": "服务器未报告任何模型。请先下载或加载一个。",
  "Proveedor local: no necesita clave. Usa la dirección por defecto; puedes cambiar IP y puerto en Ajustes → Proveedores.": "本地提供商：无需密钥。使用默认地址；可在设置 → 提供商中更改 IP 和端口。",
  "Traducciones con IA": "AI 翻译",
  "Traduce este contenido a otro idioma. Cada idioma se guarda y puede regenerarse o eliminarse.": "将此内容翻译为其他语言。每种语言都会被保存，可重新生成或删除。",
  "Traduciendo…": "正在翻译…",
  "Genera la traducción con el modelo de IA configurado": "使用配置的 AI 模型生成翻译",
  "La traducción de un texto largo puede tardar. Puedes cerrar esta ventana: se guardará y aparecerá aquí al volver.": "长文本的翻译可能需要一些时间。你可以关闭此窗口：翻译会被保存，返回时会显示在这里。",
  "Cargando traducciones…": "正在加载翻译…",
  "Aún no hay traducciones. Elige un idioma y genera la primera.": "还没有翻译。选择一种语言并生成第一个。",
  "Regenerar esta traducción": "重新生成此翻译",
  "Eliminar traducción": "删除翻译",
  "¿Eliminar la traducción a {lang}? Esta acción no se puede deshacer.": "删除 {lang} 翻译？此操作无法撤销。",
  "Seleccionar todo": "全选",
  "Deseleccionar todo": "取消全选",
  "Eliminar seleccionados": "删除所选",
  "Eliminar seleccionadas": "删除所选",
  "Eliminar informes": "删除报告",
  "¿Eliminar {n} informes guardados? Esta acción no se puede deshacer.": "删除 {n} 份已保存的报告？此操作无法撤销。",
  "{n} informes eliminados.": "已删除 {n} 份报告。",
  "Eliminar inmersiones": "删除沉浸",
  "¿Eliminar {n} inmersiones y todo su progreso? Esta acción no se puede deshacer.": "删除 {n} 个沉浸及其全部进度？此操作无法撤销。",
  "Nueva inmersión": "新建沉浸",
  "Domina un tema de tu corpus: panorama, estaciones con citas literales, contrastes, fronteras y examen final. Todo queda grabado para retomarlo.": "掌握你语料库中的一个主题：全景、带原文引用的站点、对比、边界和期末测验。一切都会被保存，以便随时继续。",
  "Domina un tema de tu corpus: el contenido y el progreso se guardan para retomarlos; tus respuestas se borran al reiniciar.": "掌握你语料库中的一个主题：内容和进度会被保存以便继续；你的答案会在重新开始时清除。",
  "Buscar entre tus inmersiones…": "搜索你的沉浸…",
  "Cargando inmersiones…": "正在加载沉浸…",
  "Ninguna inmersión coincide con tu búsqueda.": "没有沉浸与你的搜索匹配。",
  "Aún no hay inmersiones. Crea la primera y quedará aquí, con su progreso y tus respuestas, lista para retomarla.": "还没有沉浸。创建第一个，它会连同进度和你的答案保留在这里，随时可以继续。",
  "Aún no hay inmersiones. Crea la primera y quedará aquí, con su progreso, lista para retomarla.": "还没有沉浸。创建第一个，它会连同进度保留在这里，随时可以继续。",
  "Reiniciar borra las respuestas anteriores y comienza el recorrido desde el principio.": "重新开始会清除之前的答案，并从头开始整个流程。",
  "Elige el tema y el alcance. Antes de generar verás qué sabe tu corpus (sin IA).": "选择主题和范围。生成之前，你会看到你的语料库了解什么（暂不使用 AI）。",
  "Novedades": "新功能",
  "Esto es lo nuevo en esta versión de Nodus.": "这是此版本 Nodus 中的新内容。",
  "¡Entendido!": "知道了！",
  "Plegar": "折叠",
  "Desplegar": "展开",
  "Elige las colecciones a monitorizar. Despliega cualquier colección para elegir subcolecciones concretas si una es demasiado grande. Se incorporan metadatos; los análisis se lanzan manualmente salvo que actives automatización en Ajustes.": "选择要监控的集合。如果某个集合太大，可展开它以选择具体的子集合。元数据会被导入；除非在设置中启用自动化，否则分析将手动运行。",
  "Fuentes primarias": "原始资料",
  "Genealogía": "谱系学",
  "próximamente": "即将推出",
  "Tipo de bóveda: {type}.": "资料库类型：{type}。",
  "Mi bóveda": "我的资料库",
  "TU PRIMERA BÓVEDA": "你的第一个资料库",
  "Vamos a crear tu primera bóveda": "我们来创建你的第一个资料库",
  "Ponle un nombre y elige su modo. El modo decide qué secciones verás y cómo trabaja la IA contigo; puedes crear más bóvedas, de otros modos, cuando quieras.": "为它命名并选择模式。模式决定你会看到哪些板块以及 AI 如何与你协作；你可以随时创建更多其他模式的资料库。",
  "Después el asistente te ayudará a elegir su modelo de IA y su modelo de embeddings. Puedes cambiar el nombre en cualquier momento desde el selector de bóvedas.": "随后向导会帮助你选择其 AI 模型和嵌入模型。你可以随时从资料库切换器中重命名。",
  "Crear mi bóveda": "创建我的资料库",
  "Nombre de la bóveda": "资料库名称",
  "Tipo de bóveda": "资料库类型",
  "Personas": "人物",
  "Buscar por nombre o variante…": "按姓名或变体搜索…",
  "Añadir persona": "添加人物",
  "Importar un árbol GEDCOM (Gramps, Ancestry…)": "导入 GEDCOM 家谱（Gramps、Ancestry…）",
  "Importar": "导入",
  "Exportar a GEDCOM para Gramps / Ancestry": "导出为 GEDCOM 供 Gramps / Ancestry 使用",
  "Buscar registros que podrían ser la misma persona": "查找可能是同一个人的记录",
  "Revisar coincidencias": "审核匹配项",
  "Revisar parentescos propuestos a partir de la evidencia": "审核根据证据推断的亲属关系",
  "Parentescos sugeridos": "建议的亲属关系",
  "Aún no hay personas. Se crean al analizar fuentes primarias o añadiéndolas a mano.": "还没有人物。它们会在分析原始资料或手动添加时创建。",
  "sin fechas": "无日期",
  "Selecciona una persona para ver su ficha, sus eventos y la evidencia que la respalda.": "选择一个人物以查看其档案、事件以及支持证据。",
  "Propuestos a partir de la evidencia de las fuentes. Tú confirmas; nada se añade al árbol solo.": "根据资料中的证据推断。由你确认；不会自动向家谱中添加任何内容。",
  "No hay parentescos por revisar.": "没有需要审核的亲属关系。",
  "¿{a} y {b} eran cónyuges?": "{a} 和 {b} 是配偶吗？",
  "¿{parent} era progenitor(a) de {child}?": "{parent} 是 {child} 的父/母吗？",
  "mención explícita": "明确提及",
  "registro": "记录",
  "Confirmar parentesco": "确认亲属关系",
  "Descartar": "忽略",
