  "Elegir tipo de documento…": "选择文档类型…",
  "Opcional: archivo, repositorio, cita, URL…": "可选：档案、存储库、引注、URL…",
  "Año del documento (según su fecha registrada), no el de subida.": "文档年份（依据其记录的日期），而非上传日期。",
