  "Resume el contenido de esta fila en una o dos frases claras.": "用一两句清晰的话概括此行内容。",
  "Clasifica esta fila en una categoría breve (una o dos palabras). Devuelve solo la categoría.": "将此行归入一个简短的类别（一两个词）。只返回类别。",
  "Extrae de 3 a 5 palabras clave separadas por comas. Devuelve solo las palabras clave.": "提取 3 到 5 个用逗号分隔的关键词。只返回关键词。",
  "Indica el sentimiento del contenido: positivo, negativo o neutro. Devuelve solo una palabra.": "判断内容的情感倾向：正面、负面或中性。只返回一个词。",
  "Traduce el contenido principal de esta fila al inglés. Devuelve solo la traducción.": "将此行的主要内容翻译为英语。只返回译文。",
  "Describe en 40-60 palabras la imagen adjunta a esta fila.": "用 40-60 个词描述此行附带的图片。",
  "Transcribe literalmente todo el texto que aparezca en la imagen o archivo adjunto. Devuelve solo la transcripción.": "逐字转写图片或附件中出现的所有文本。只返回转写内容。",
