  "Actualizar vista": "更新视图",
  "Demo de bases de datos": "数据库演示",
  "Tres tablas de investigación con todos los tipos de columna, relaciones, registros, análisis, una conversación y notas de ejemplo. Incluye un tutorial guiado.": "三张研究表，涵盖所有列类型、关系、记录、分析、一段对话和示例笔记。包含引导式教程。",
  "Cargar demo de bases de datos": "加载数据库演示",
  "Cargar datos de ejemplo": "加载示例数据",
  "Tutorial de bases de datos": "数据库教程",
  "La lista de bases de datos, la tabla con columnas tipadas, la edición de celdas y las secciones de análisis y chat.": "数据库列表、带类型的列表格、单元格编辑，以及分析和聊天部分。",
  "Se mostrará el tutorial de bases de datos.": "将显示数据库教程。",
  "Bienvenido al modo bases de datos": "欢迎使用数据库模式",
  "Este es el modo bases de datos de Nodus: un gestor de tablas al estilo Notion, integrado en tu app. Te enseño en un minuto sus piezas con tres bases de datos de ejemplo ya cargadas. Puedes salir cuando quieras y volver a ver el tutorial desde Ajustes.": "这是 Nodus 的数据库模式：一个内置于应用中的 Notion 风格表格管理器。我将用一分钟通过三个已加载的示例数据库带你了解它的各个部分。你可以随时退出，并从设置中重新观看教程。",
  "Tus bases de datos": "你的数据库",
  "En la barra lateral aparecen todas tus bases de datos. Cada una tiene un identificador único autogenerado. Pulsa una para abrirla, o el botón + para crear una nueva. Aquí abajo están también las secciones de Análisis y Chat.": "所有数据库都会显示在侧边栏中。每个数据库都有一个自动生成的唯一标识符。点击即可打开，或点击 + 按钮新建一个。下方还有分析和聊天部分。",
  "La tabla": "表格",
  "Cada base de datos es una tabla de columnas tipadas: título, texto, número, fecha, hora, selección, selección múltiple y casilla. Arriba verás el número total de entradas y el porcentaje que suponen del total de todas tus bases de datos.": "每个数据库都是一张包含各类列的表格：标题、文本、数字、日期、时间、单选、多选和复选框。顶部会显示条目总数，以及它们占你所有数据库总数的百分比。",
  "Edita directamente": "就地编辑",
  "Haz clic en cualquier celda para editarla al momento. Las columnas de selección muestran opciones con color que puedes añadir sobre la marcha; las casillas se marcan con un clic. Pasa el ratón por una fila para borrarla.": "点击任意单元格即可立即编辑。单选列会显示带颜色的选项，你可以随时添加；复选框点击即可切换。将鼠标悬停在某行上可将其删除。",
  "Columnas a tu medida": "按需定制列",
  "Pulsa la cabecera de una columna para renombrarla, cambiar su tipo o gestionar sus opciones, y usa el botón + del final de la cabecera para añadir nuevas columnas. Con «Nueva fila» añades registros.": "点击列标题可重命名、更改类型或管理其选项，并使用标题末尾的 + 按钮添加新列。通过「新建行」添加记录。",
  "Análisis (próximamente)": "分析（即将推出）",
  "Aquí podrás elegir una base de datos y obtener estadísticas automáticas más un informe con IA, con gráficos y el cálculo a la vista para que sea reproducible. Llega en una próxima fase.": "在这里，你可以选择一个数据库，获取自动统计数据和 AI 报告，附带图表和可见的计算过程，以确保可复现。将在后续阶段推出。",
  "Chat de datos (próximamente)": "数据聊天（即将推出）",
  "Un chat adaptado para conversar con una o varias de tus bases de datos, capaz de generar gráficos y consultas reproducibles. También llega en una próxima fase.": "专为与你的一个或多个数据库对话而设计的聊天功能，能够生成图表和可复现的查询。同样将在后续阶段推出。",
  "Listo para tus datos": "为你的数据做好准备",
  "Esto es una demostración con datos de ejemplo. Cuando quieras empezar con los tuyos, crea una base de datos desde la barra lateral y añade tus columnas. Pronto podrás además importar CSV y subir archivos en masa.": "这是一个使用示例数据的演示。当你想开始使用自己的数据时，从侧边栏创建一个数据库并添加列。很快你还可以导入 CSV 并批量上传文件。",
