  "No, ahora no": "否，暂不",
  "Nodus puede extraer conceptos, relaciones y citas textuales para crear el mapa de Ideas y el grafo de estudio.": "Nodus 可以提取概念、关系和原文引文，用于创建观点图谱和学习图谱。",
  "El análisis se realizará en este dispositivo con el modelo seleccionado; el archivo no saldrá del equipo.": "分析将使用所选模型在本设备上进行；文件不会离开本机。",
  "Se enviarán al proveedor indicado el título y el texto extraído necesario. El archivo original permanecerá en tu dispositivo.": "会将标题和必要的提取文本发送给指定的提供商。原始文件将保留在你的设备上。",
  "caracteres extraídos": "个已提取字符",
  "No volver a preguntar": "不再询问",
