  "Sin modelo alternativo": "无备用模型",
  "Modelo del proveedor": "提供商模型",
  "Heredar modelo principal": "继承主要模型",
  "Lleva tus notas, datos de estudio, materiales y grabaciones, borradores, búsquedas guardadas, auditorías de relaciones, bases de datos y Copias protegidas a otro equipo. Al importar se fusiona por fecha: gana la versión más reciente; las eliminaciones de Copias protegidas también se sincronizan mediante borrado lógico.": "将你的笔记、学习数据、材料和录音、草稿、已保存的搜索、关系审计、数据库和保护副本带到另一台电脑。导入时按日期合并：以最新版本为准；保护副本的删除也通过软删除进行同步。",
  "Esta acción elimina datos de forma permanente. ¿Quieres continuar?": "此操作会永久删除数据。是否继续？",
  "Administración del vault de estudio": "学习资料库管理",
  "Comprobaciones locales de SQLite, almacenamiento, índices, huérfanos y papelera.": "SQLite、存储、索引、孤立项和回收站的本地检查。",
