  "Analíticas de estudio desactivadas": "学习分析已停用",
  "Puedes activarlas en Ajustes → Modelos IA. Los repasos siguen funcionando localmente.": "你可以在设置 → AI 模型中启用它们。复习仍可在本地进行。",
  "Modelos de IA": "AI 模型",
  "Un modelo general atiende conversación, análisis, resúmenes y las demás tareas de texto. Las capacidades especializadas se configuran debajo.": "一个通用模型负责对话、分析、摘要及其他文本任务。专业能力在下方配置。",
  "El modelo general sigue siendo la base. Cada selector vacío hereda de él; los modelos de las herramientas se guardan solo en el vault actual.": "通用模型仍是基础。每个空白选择器都会继承它；工具的模型仅保存在当前资料库中。",
  "Cada tarea utiliza el modelo concreto seleccionado. Los modelos de las herramientas se guardan solo en el vault actual.": "每项任务使用所选的特定模型。工具的模型仅保存在当前资料库中。",
  "Modelo general de texto": "通用文本模型",
  "Conversación, análisis, resúmenes y fallback de cualquier tarea sin modelo propio.": "对话、分析、摘要，以及任何没有专属模型的任务的备用模型。",
  "Conversación, análisis, resúmenes y demás tareas de texto.": "对话、分析、摘要及其他文本任务。",
  "Este modelo consume la cuota de tu suscripción, no crédito de API. Un análisis completo del corpus puede agotar el límite semanal o mensual de tu plan.": "此模型消耗你的订阅配额，而非 API 额度。对语料库进行完整分析可能会用尽你套餐的每周或每月限额。",
  "Este modelo local es de visión y no extrae ideas de forma fiable (tiende a divagar y no cerrar el JSON). Para extracción, elige Gemma 4 E2B u otro modelo mayor.": "此本地模型面向视觉，无法可靠地提取观点（容易偏离主题且不会闭合 JSON）。如需提取，请选择 Gemma 4 E2B 或更大型的模型。",
  "Estos pesos son los mismos que Nodus descarta entre sus modelos integrados: al extraer ideas divagan y no cierran el JSON. Puedes usarlos igualmente, pero para extracción conviene un modelo mayor.": "这些权重与 Nodus 在内置模型中排除的相同：提取观点时会偏离主题且不闭合 JSON。你仍可以使用它们，但提取更适合使用更大型的模型。",
  "El paso falló sin dejar un motivo. Reintenta; si vuelve a fallar, revisa el modelo en Ajustes → Modelos de IA.": "该步骤失败且未记录原因。请重试；如果再次失败，请在设置 → AI 模型中检查模型。",
  "Todavía no hay ningún modelo entre los que elegir. Pulsa «Cargar modelos» para ver los de tus proveedores, o marca los que quieras como favoritos en Ajustes → Proveedores de IA y modelos.": "目前没有可供选择的模型。点击「加载模型」查看你的提供商提供的模型，或在设置 → AI 提供商和模型中将要用的标记为收藏。",
  "Sin respuesta de {list}. Revisa su clave o que el servidor local esté abierto.": "{list} 无响应。请检查其密钥，或确认本地服务器已启动。",
  "solo visión": "仅视觉",
  "Este modelo no puede usarse para extracción de ideas.": "此模型不能用于提取观点。",
  "Uso mi plan gratuito de este proveedor": "我使用此提供商的免费套餐",
  "Ajusta las peticiones a los límites del nivel gratuito (recorta la longitud de salida y espera si se alcanza el límite por minuto) para que el análisis no falle. Déjalo desmarcado si pagas por uso.": "将请求调整到免费层级的限制内（缩短输出长度，并在达到每分钟限额时等待），以免分析失败。如果你按用量付费，请保持未勾选。",
