  "Se eliminará «{model}» del almacenamiento de Nodus. Si está seleccionado, las funciones que lo usan dejarán de funcionar hasta que elijas otro modelo o vuelvas a descargarlo.": "将从Nodus存储中删除「{model}」。如果它已被选中，使用它的功能将停止工作，直到你选择其他模型或重新下载它。",
  "Cambiar modelo de embeddings": "更改嵌入模型",
  "Los embeddings creados con el modelo anterior no son compatibles con el nuevo. Nodus conservará los datos, pero tendrás que reindexar para que la búsqueda semántica y las relaciones usen el nuevo modelo. ¿Cambiar de todos modos?": "使用旧模型创建的嵌入与新模型不兼容。Nodus会保留数据，但你必须重新建立索引，语义搜索和关系才能使用新模型。仍要更改吗？",
  "Cambiar modelo": "更改模型",
  "Si cambias de modelo de embeddings, los vectores anteriores no servirán con el nuevo modelo y tendrás que reindexar.": "如果更换嵌入模型，原有向量将无法与新模型配合使用，你必须重新建立索引。",
