  "6. Texto o transcripción": "6. 文本或转录",
  "Opcional. Añade una transcripción o texto que deba ser buscable e indexado…": "可选。添加需要可搜索和索引的转录或文本…",
  "Si el archivo permite extraer texto automáticamente, Nodus lo hará al guardarlo. Este campo permite añadirlo o sustituirlo manualmente.": "如果文件可以自动提取文本，Nodus 将在保存时完成提取。此字段可让你手动添加或替换文本。",
