  "Verificar": "验证",
  "Verificar de nuevo": "重新验证",
  "Cambios sin guardar": "未保存的更改",
  "Error al guardar": "保存错误",
  "Chat con el corpus": "与语料库对话",
  "Mejora de texto": "文本优化",
  "Detalles y fuente": "详情与来源",
  "Verificar ideas extraídas": "验证提取的观点",
  "Cada idea aparece con su tipo (afirmación, hallazgo, constructo, método o marco), la obra de la que procede y la cita textual que la sostiene. Abre el detalle para comprobar si la lectura automática coincide con la tuya.": "每个观点都会显示其类型（主张、发现、构念、方法或框架）、所属文献及支撑它的原文引用。打开详情可核对自动解读是否与你的判断一致。",
  "Busca por palabras clave a través de ideas, obras, huecos, temas, autores y notas. Los resultados te llevan directamente al detalle correspondiente en cada vista.": "按关键词搜索观点、文献、空白、主题、作者和笔记。结果会直接带你进入各视图中对应的详情。",
  "Tu espacio de notas": "你的笔记空间",
  "Crea carpetas y notas en Markdown. Captura respuestas del asistente, borradores del taller de escritura, síntesis de debates e ideas individuales. Las citas internas (nodus://) permanecen clicables.": "创建文件夹和 Markdown 笔记。记录助手回答、写作工作坊草稿、辩论综述和单个观点。内部引用（nodus://）保持可点击。",
  "Debates: la estructura de una contradicción": "辩论：矛盾的结构",
  "Cada relación de contradicción o refutación se despliega como un debate de dos bandos con sus autores, evidencias y cronología. Pides una síntesis al modelo para entender la tensión y decides cómo tu trabajo puede resolverla o aprovecharla.": "每条矛盾或反驳关系都会展开为一场两方辩论，包含双方作者、证据和时间线。你向模型请求综述以理解这种张力，再决定你的工作如何化解或利用它。",
  "Mapa de cobertura: tu pregunta descompuesta": "覆盖图：拆解你的问题",
  "Escribe tu pregunta de investigación y Nodus la desglosa en subpreguntas. Después mapea cuáles cubre tu corpus, cuáles parcialmente y cuáles quedan sin literatura. Es la herramienta para convertir una intuición vaga en un plan de búsqueda estructurado.": "输入你的研究问题，Nodus 会将其拆解为子问题。随后它会标出你的语料库覆盖了哪些、部分覆盖了哪些、哪些尚无文献。这是把模糊直觉转化为结构化检索计划的工具。",
  "Notas: tu cuaderno de investigación": "笔记：你的研究笔记本",
  "A lo largo del proceso habrás generado hallazgos en el asistente, borradores en el taller y síntesis de debates. Las Notas te permiten organizar todo ello en carpetas jerárquicas — piensa en capítulos y secciones — con un editor Markdown que conserva las citas clicables. Las ideas manuales que crees aquí se integran directamente en el grafo.": "在研究过程中，你会在助手中生成发现、在工作坊中生成草稿、在辩论中生成综述。笔记让你把这一切整理到层级文件夹中——可以理解为章节和小节——并配有保持引用可点击的 Markdown 编辑器。你在此创建的手动观点会直接进入图谱。",
  "Inicio resume el estado de tu corpus, los análisis pendientes y el siguiente paso recomendado. La investigación es iterativa: escaneas más obras, vuelven a aparecer ideas y huecos, refinas la ruta y el borrador. Vuelve aquí entre vueltas. Puedes relanzar este recorrido desde Ajustes → Ayuda.": "首页汇总你的语料库状态、待处理的分析和推荐的下一步。研究是迭代的：你扫描更多文献，观点和空白会再次出现，你不断优化路线和草稿。每一轮之间回到这里。你可以从 设置 → 帮助 重新启动此导览。",
  "RECUPERACIÓN ACTIVADA": "恢复已启用",
  "Tus datos ya están protegidos": "你的数据现已受到保护",
  "Tus datos se han recuperado": "你的数据已恢复",
  "bóveda(s)": "资料库",
  "Clave de recuperación independiente": "独立恢复密钥",
  "Permite recuperar tus copias aunque olvides la contraseña.": "即使忘记密码，也能恢复你的备份。",
  "Guarda el kit fuera de este dispositivo. Podrás restaurar con la contraseña o con la clave de recuperación.": "请将恢复套件保存在此设备之外。你可以使用密码或恢复密钥进行恢复。",
  "Continuar a Nodus": "继续进入 Nodus",
  "PROTECCIÓN DE DATOS": "数据保护",
  "Hemos detectado una instalación anterior": "我们检测到已有的安装",
  "Elige dónde proteger Nodus": "选择 Nodus 的保护位置",
  "Tus bóvedas actuales no se moverán ni se modificarán. Crearemos una primera copia cifrada y verificada antes de activar la recuperación.": "你当前的资料库不会被移动或修改。我们会在启用恢复前创建一个经过验证的加密备份。",
  "Configura una carpeta segura antes de empezar. Tus bóvedas seguirán trabajando localmente y Nodus guardará aquí copias recuperables.": "开始前请配置一个安全文件夹。你的资料库仍将在本地工作，Nodus 会在此保存可恢复的备份。",
  "La base de datos activa nunca se abre directamente desde Google Drive o Dropbox: así evitamos conflictos y corrupción.": "活动数据库绝不会直接从 Google Drive 或 Dropbox 打开：这样可避免冲突和损坏。",
  "Migrar y proteger este equipo": "迁移并保护此电脑",
  "Crear carpeta segura": "创建安全文件夹",
  "Recuperar otro equipo": "恢复其他电脑",
  "1. Selecciona una carpeta vacía": "1. 选择一个空文件夹",
  "1. Selecciona la carpeta existente": "1. 选择现有文件夹",
  "Puede ser una carpeta local o una carpeta sincronizada por Google Drive, Dropbox, iCloud u otro servicio. Debe estar vacía.": "可以是本地文件夹，也可以是由 Google Drive、Dropbox、iCloud 或其他服务同步的文件夹。必须为空。",
  "Busca la carpeta que contiene nodus-recovery.json y sus copias.": "选择包含 nodus-recovery.json 及其备份的文件夹。",
  "2. Todo Nodus quedará protegido": "2. 整个 Nodus 都将受到保护",
  "Sin selecciones ni exclusiones: todas las bóvedas, documentos, preferencias, historiales, medios y claves API se incluirán automáticamente.": "无需选择或排除：所有资料库、文档、偏好设置、历史记录、媒体文件和 API 密钥都会自动纳入。",
  "2. Elige una copia": "2. 选择一份备份",
  "La más reciente aparece seleccionada. Puedes recuperar una versión anterior.": "默认选中最新的一份。你也可以恢复较旧的版本。",
  "3. Crea una contraseña maestra": "3. 创建主密码",
  "3. Introduce una credencial": "3. 输入凭据",
  "Protege tus copias junto con una clave de recuperación independiente. Debe tener al menos 8 caracteres.": "为你的备份配置独立恢复密钥。密码至少需要 8 个字符。",
  "Puedes usar la contraseña maestra o la clave de recuperación de tu kit.": "你可以使用主密码或恢复套件中的恢复密钥。",
