  "Al adjuntar, además de guardar el archivo:": "附加时，除保存文件外：",
  "Columna vacía con nombre de archivo: lista para adjuntar": "带有文件名样式的空列：可附加文件",
  "Con {n} archivos esto puede tardar horas. Puedes adjuntarlos ahora y hacerlo después por columnas.": "有 {n} 个文件时，这可能需要数小时。你可以现在附加，之后再按列处理。",
