  "Ej.: @@###-@@### · # dígito, @ letra, * cualquier cosa": "例如：@@###-@@### · # 数字，@ 字母，* 任意字符",
  "Ej.: {v}": "例如：{v}",
  "Elige archivos o una carpeta completa. Nodus empareja cada archivo con su fila por el nombre exacto y, si no, por el código del catálogo que compartan (LV001-FG001).": "选择文件或整个文件夹。Nodus 会按完全相同的名称将每个文件与其行配对；若无法匹配，则按它们共有的目录代码（LV001-FG001）配对。",
