  "El hilo es público: describe los casos en abstracto, sin datos reales de alumnado.": "该帖子是公开的：请抽象描述案例，不要包含真实的学生数据。",
  "Qué esperarías poder hacer en esta sección": "你希望在这一节能做什么",
