  "Epíteto o título (opcional)": "称号或头衔（可选）",
  "Con el nombre basta para empezar. El resto de la ficha se rellena después.": "有名字就足以开始。档案的其余内容稍后再填。",
  "Volver a los personajes": "返回角色",
