  "Descendencia": "后代",
  "Notas libres sobre este personaje, en Markdown…": "关于此角色的自由笔记，Markdown格式…",
  "Lo que se ve. Es lo único que alimenta la generación de imágenes.": "可见的外貌。它是图像生成的唯一依据。",
  "Rasgos, complexión, ropa, marcas distintivas…": "五官、体型、衣着、显著特征…",
  "Personalidad": "性格",
  "Cómo es y cómo habla.": "其为人与说话方式。",
  "Carácter, motivaciones, miedos, forma de hablar…": "性格、动机、恐惧、说话方式…",
  "Trasfondo": "背景",
  "De dónde viene y qué le ha pasado.": "其来历与过往经历。",
  "Origen, historia previa, cómo llega al punto en que empieza el relato…": "出身、过往经历、如何走到故事开始之处…",
  "Semilla visual": "视觉种子",
  "Un texto corto y estable que se añade a TODAS las imágenes que generes de este personaje. Es lo que consigue que se parezca a sí mismo de una imagen a otra, así que conviene cambiarlo lo menos posible.": "一段简短而固定的文本，会添加到该角色生成的每一张图像中。它能让角色在不同图像中保持一致的外貌，因此应尽量少修改。",
  "p. ej. «semielfo de rasgos afilados, pelo negro recogido, ojos ámbar»": "例如«五官锐利的半精灵，黑发束起，琥珀色眼睛»",
  "Usar la apariencia como semilla": "将外貌用作种子",
  "Redacta una biografía narrativa a partir de la ficha: su descripción, sus eventos y sus vínculos.": "根据档案撰写叙事传记：其描述、经历的事件与羁绊。",
  "Rellena al menos la descripción, un evento o un vínculo antes de generar la biografía.": "生成传记前，请至少填写描述、一个事件或一条羁绊。",
  "Generada con IA": "AI生成",
  "Nombres y alias": "姓名与化名",
  "Añadir alias": "添加化名",
  "Sin nombres alternativos.": "无其他名称。",
  "Nuevo nombre o alias": "新名称或化名",
  "Un nombre verdadero, un título, un apodo o cómo le llaman en otra lengua.": "真名、头衔、绰号，或其他语言中的称呼。",
  "El nombre…": "名称…",
  "Tipo de nombre": "名称类型",
