  "p. ej. 1204 (admite negativos)": "例如 1204（可为负数）",
  "La fecha se escribe como quieras; el año del mundo es lo que ordena la lista.": "日期可随意书写；列表按世界年份排序。",
  "{n} sin año del mundo: aparecen al final hasta que les pongas uno.": "{n} 条无世界年份：在设置之前会一直排在末尾。",
  "Nacimiento (texto libre)": "出生（自由文本）",
  "Muerte (texto libre)": "死亡（自由文本）",
  "Año del mundo · nacimiento": "世界年份 · 出生",
  "Año del mundo · muerte": "世界年份 · 死亡",
  "La fecha se muestra tal como la escribas. El año del mundo es un entero y sirve solo para ordenar.": "日期按你所写显示。世界年份为整数，仅用于排序。",
  "Subir imagen": "上传图像",
  "Arrastra para encuadrar": "拖动以调整构图",
  "Arrastra la imagen para encuadrarla y usa el zoom.": "拖动图像调整构图，并使用缩放。",
  "Retrato con IA": "AI肖像",
  "Se usa la apariencia y la semilla visual de la ficha, así que el personaje mantiene el mismo aspecto entre imágenes.": "使用档案中的外貌与视觉种子，因此角色在图像之间保持一致的外貌。",
  "Escribe primero la apariencia del personaje en la sección Descripción.": "请先在描述部分填写角色的外貌。",
  "Solo para esta imagen: pose, gesto, ropa, luz… (opcional)": "仅用于此图像：姿势、动作、衣着、光线…（可选）",
  "Tu mundo": "你的世界",
  "Construye un mundo de ficción pieza a pieza. Empieza por los personajes: sus nombres y alias, los hechos de su vida, sus vínculos y su descripción, con retratos y biografías que puedes generar cuando te sirvan.": "一点一滴构建你的虚构世界。从角色开始：他们的姓名与化名、生平事件、羁绊与描述，还可以在需要时生成肖像和传记。",
  "Personajes recientes": "最近的角色",
  "Ver todos": "查看全部",
  "En construcción": "建设中",
  "Las demás secciones del menú ({sections}) aparecen atenuadas porque todavía no están construidas. Se irán activando una a una.": "菜单中的其他部分（{sections}）因尚未构建而显示为灰色。它们将陆续启用。",
  "enciclopedia, lugares, facciones, culturas, cronología, mapa, relaciones, escenas y manuscritos": "百科全书、地点、派系、文化、年表、地图、关系、场景和手稿",
  "n. {date}": "生于 {date}",
  "†︎ {date}": "†︎ {date}",
  "Tipo de imagen": "图像类型",
  "Cuerpo entero": "全身",
  "Expresión": "表情",
  "A otra edad": "其他年龄",
  "Atuendo": "装束",
  "Otra": "其他",
  "Sin imágenes todavía.": "尚无图像。",
  "Se generará una imagen de tipo «{kind}» con la apariencia y la semilla visual de la ficha.": "将使用档案中的外貌与视觉种子生成一张«{kind}»类型的图像。",
  "Usar como avatar": "用作头像",
  "Ver detalles": "查看详情",
  "Imagen del personaje": "角色图像",
  "Subida por ti": "由你上传",
  "Prompt que la generó": "生成它的提示词",
  "p. ej. «De pie en la sala del trono»": "例如«站在王座厅中»",
  "¿Eliminar esta imagen de la galería? Si es el avatar del personaje, el avatar se conserva.": "从图库中删除此图像？如果它是角色的头像，头像将保留。",
  "Arco": "弧光",
  "Qué quiere": "想要什么",
  "El objetivo que persigue y que mueve la trama.": "其追求并推动情节的目标。",
  "Qué necesita": "需要什么",
  "Lo que le hace falta de verdad, y que rara vez es lo que quiere.": "其真正需要的东西，而这很少是其想要的。",
  "Su defecto": "其缺陷",
  "Lo que le impide conseguirlo.": "阻碍其达成目标之物。",
  "La mentira que se cree": "其相信的谎言",
  "Lo que da por cierto sobre sí mismo o sobre el mundo, y no lo es.": "其自以为真实、实则不然的关于自身或世界的认知。",
  "Su herida": "其创伤",
  "De dónde salió esa mentira.": "那谎言从何而来。",
  "Voz": "声音",
  "Registro": "语域",
  "Culto, soez, arcaizante, telegráfico…": "文雅、粗俗、古语、简洁…",
  "Tics y muletillas": "口头禅与习惯用语",
  "Lo que repite, y lo que no diría nunca.": "其反复说的话，以及绝不会说的话。",
  "Muestra de diálogo": "对话示例",
  "Dos o tres líneas suyas hablando. Es lo que la IA imita.": "其说话的两三行。AI会模仿这段内容。",
  "Escuchar la muestra": "播放示例",
  "Habilidades": "能力",
  "Añadir habilidad": "添加能力",
  "Nueva habilidad": "新建能力",
