  "Eliminar habilidad": "删除能力",
  "¿Eliminar esta habilidad?": "删除此能力？",
  "Sin habilidades registradas.": "无记录能力。",
  "Nombre de la habilidad": "能力名称",
  "Qué hace": "作用",
  "Coste": "代价",
  "Qué le cuesta usarla": "使用它需要付出什么",
  "Límite": "限制",
  "Qué NO puede hacer con ella": "它不能做什么",
  "El límite es lo que hace interesante a un poder: sin él resuelve cualquier escena.": "限制才让能力有趣：没有限制，它就能解决任何场景。",
  "Sin límite definido: una habilidad sin límite resuelve cualquier escena.": "未设置限制：没有限制的能力能解决任何场景。",
  "Es un secreto": "这是秘密",
  "Secreto": "秘密",
  "Secreto · lo conocen: {who}": "秘密 · 知情者：{who}",
  "Quién lo conoce (p. ej. «solo su hermana y el archivero»)": "谁知道（例如«只有其姐姐和档案管理员»）",
  "Los nombres secretos no aparecen en la cuadrícula de personajes.": "秘密名称不会显示在角色网格中。",
  "Quitar {name}": "移除 {name}",
  "Cómo la vive": "其如何感受",
  "Solo desde su lado: la otra persona puede vivir la misma relación de forma muy distinta.": "仅从其视角：另一方对同一段关系的感受可能大不相同。",
  "Sin especificar": "未指定",
  "Aliado": "盟友",
  "Rival": "对手",
  "Amante": "恋人",
  "Mentor": "导师",
  "Discípulo": "弟子",
  "Némesis": "宿敌",
  "Familia": "亲属",
  "Neutral": "中立",
  "Muere el año {death}, antes de nacer el año {birth}.": "死于 {death} 年，早于 {birth} 年出生。",
  "Participa en un hecho el año {year}, después de morir el año {death}.": "参与 {year} 年的事件，晚于 {death} 年死亡。",
  "Participa en un hecho el año {year}, antes de nacer el año {birth}.": "参与 {year} 年的事件，早于 {birth} 年出生。",
  "Tiene fecha de muerte pero su estado sigue siendo «vivo».": "有死亡日期，但状态仍为«在世»。",
  "Está marcado como muerto pero no consta cuándo.": "标记为已故，但未记录死亡时间。",
  "El nombre se parece mucho a «{other}»: quien lea puede confundirlos.": "名称与«{other}»很相似：读者可能会混淆。",
  "Proponer": "提议",
  "Proponiendo…": "提议中…",
  "Propuesta sin aceptar": "未接受的提议",
  "Aceptar como canon": "接受为正典",
  "Lo que va entre corchetes lo ha inventado la IA. No es canon hasta que lo aceptes.": "方括号中的内容由AI虚构。在你接受之前，它不属于正典。",
  "Solo cuenta lo que ya está en la ficha": "只叙述档案中已有的内容",
  "Rellena los huecos y marca entre corchetes lo que ha inventado": "填补空白，并用方括号标出其虚构的内容",
  "Entrevistar": "访谈",
  "Entrevistar a {name}": "访谈 {name}",
  "Hablar con el personaje en su propia voz": "以角色自己的声音交谈",
  "Responde en su voz y solo sabe lo que hay en su ficha. Nada de esta conversación se guarda.": "以其声音回答，且只知道其档案中的内容。此对话不会保存任何内容。",
  "Responde en su propia voz; las conversaciones se guardan en esta bóveda.": "以其自己的声音回答；对话会保存在此资料库中。",
  "Se eliminará «{title}» junto con todos sus mensajes e imágenes. Esta acción no se puede deshacer.": "将删除«{title}»及其所有消息和图像。此操作无法撤销。",
  "Pregúntale algo.": "向其提问。",
  "Rellena antes su descripción: sin ficha no tiene nada que contestar.": "请先填写其描述：没有档案就没有可回答的内容。",
  "Tu pregunta…": "你的问题…",
  "Preguntar": "提问",
  "«¿De qué te arrepientes?»": "«你后悔什么？»",
  "«¿A quién no soportas y por qué?»": "«你受不了谁，为什么？»",
  "«¿Qué harías si te quitaran lo que más quieres?»": "«如果有人夺走你最爱的东西，你会怎么做？»",
  "Exportar la ficha a Markdown": "将档案导出为 Markdown",
  "Ficha guardada en {path}": "档案已保存至 {path}",
  "(sin los nombres secretos ni tus notas privadas)": "（不含秘密名称和你的私人笔记）",
  "Plantilla": "模板",
  "Solo el nombre. Rellena la ficha a tu manera.": "只有名称。按你的方式填写档案。",
  "Héroe a su pesar": "不情愿的英雄",
  "Alguien a quien la trama saca de su vida sin pedirle permiso. Empieza por qué quería en realidad y qué le impide moverse.": "一个被情节不由分说拖离原有生活的人。先写其真正想要什么，以及什么令其止步不前。",
  "Tirano con razones": "有理有据的暴君",
  "Un antagonista que cree estar salvando algo. Lo importante es la mentira que se cree y de dónde salió.": "一个自以为在拯救什么的对手。重要的是其相信的谎言以及它的来源。",
  "Mentor con secreto": "怀有秘密的导师",
  "Quien enseña y calla lo que más importa. Define qué protege ocultándolo.": "传授知识却隐瞒最重要之事的人。定义其通过隐藏所保护的东西。",
  "Embaucador": "骗子",
  "Quien sobrevive hablando y cambia de bando a tiempo. Su voz es media ficha.": "靠言辞生存、及时转换阵营的人。其声音就是半份档案。",
  "Testigo": "目击者",
  "Un personaje menor que ve lo que nadie más ve. Con poco basta: qué vio y por qué calla.": "一个看到他人所不见之物的次要角色。只需一点：其看到了什么，以及为何沉默。",
  "Familias": "家族",
  "Dinastías": "王朝",
  "Calendario del mundo": "世界历法",
  "Definir las eras y los meses de tu mundo": "定义你世界的纪元与月份",
  "Opcional. Sin calendario, el año ordena la cronología igual que hasta ahora; con él, además ordena dentro de cada año y puedes elegir la fecha en vez de escribirla.": "可选。没有历法时，年份仍像现在一样为年表排序；有了它，还能在每年内排序，并且你可以选择日期而非手动输入。",
