  "Un lugar de tipo «{child}» está dentro de uno de tipo «{parent}». ¿Es a propósito?": "一个「{child}」类型的地点位于「{parent}」类型之内。这是故意的吗？",
  "¿Eliminar este lugar? Los lugares que contiene NO se borran: pasan a estar sueltos.": "删除此地点？其中包含的地点不会被删除：它们将变为未放置。",
