  "Lo que dirías de esto en una frase.": "用一句话描述你的看法。",
  "Lo que se ve: emblemas, colores, vestimenta, arquitectura.": "可见的特征：徽记、色彩、服饰、建筑。",
  "Símbolos, atuendo, cómo se reconoce a los suyos…": "符号、装束、如何辨认其成员…",
  "Lo que se añade a todas las imágenes para que se parezcan entre sí.": "会附加到所有图片中，使其风格统一。",
  "p. ej. «heráldica de cuervo negro sobre campo gris, plata bruñida»": "例如「灰底黑鸦纹章、抛光银饰」",
  "p. ej. «los espías de la corte, que ya no responden ante nadie»": "例如「宫廷密探，已不再听命于任何人」",
  "{from} → {to}": "{from} → {to}",
  "¿Eliminar esto? Los personajes NO se borran: solo dejan de pertenecer.": "要删除吗？角色不会被删除：只是不再属于该组织。",
