  "Lo que ocurre en la escena, en tus palabras.": "用你自己的话描述场景中发生的事。",
  "Quién quiere qué, quién se lo impide y cómo acaba…": "谁想要什么、谁从中阻挠，以及结局如何…",
  "Quién aparece": "登场人物",
  "Añadir personaje a la escena": "向场景添加角色",
  "Crea antes algún personaje.": "请先创建角色。",
  "¿Eliminar esta escena? Los personajes que aparecen en ella NO se borran.": "删除此场景？其中登场的角色不会被删除。",
  "El año es cuándo ocurre en el mundo; el orden es dónde va en el relato. Un prólogo ambientado siglos antes va primero en el relato y último en la cronología.": "年份是它在该世界中发生的时间；顺序是它在叙事中的位置。设定在几个世纪前的序章在叙事中排在最前，在时间线上排在最后。",
  "Apariciones": "登场",
  "En orden del relato, no de la cronología.": "按叙事顺序，而非时间线顺序。",
  "Secretos": "秘密",
  "Añadir secreto": "添加秘密",
  "Qué esconde…": "隐藏着什么…",
  "No esconde nada por ahora.": "目前没有隐藏任何事。",
  "Revelado": "已揭晓",
  "Además sabe": "还知道",
  "Diseña unidades para el docente o apuntes para entregar al alumnado, siempre desde tus fuentes.": "为教师设计教学单元，或为学生准备讲义，始终基于你的资料。",
  "Elige si necesitas una planificación para impartir la lección o apuntes listos para entregar.": "选择你需要授课用的教案，还是可直接分发的讲义。",
  "Elige si necesitas apuntes para aprender o una planificación para enseñar el tema.": "选择你需要用于学习的笔记，还是用于讲授该主题的教案。",
  "Escribe el tema o la lección que quieres preparar. El informe diseñará objetivos, secuencia, actividades y evaluación usando tus materiales.": "输入你想准备的主题或课程。报告将使用你的材料设计目标、序列、活动和评估。",
  "Escribe el tema de los apuntes. El informe lo explicará paso a paso con ejemplos y autoevaluación usando tus materiales.": "输入笔记的主题。报告将使用你的材料，通过示例和自测逐步讲解。",
  "Público objetivo y producto": "目标受众与产出",
  "Docente · planificación de la lección": "教师 · 教案",
  "Alumnado · apuntes para entregar": "学生 · 分发讲义",
  "Generará objetivos, secuencia, actividades, comprobaciones de comprensión y evaluación para el docente.": "将为教师生成目标、序列、活动、理解检验和评估。",
  "Generará explicaciones, definiciones, ejemplos, síntesis y autoevaluación dirigidos al alumnado.": "将为学生生成讲解、定义、示例、综述和自测。",
  "En «Crear», Unidades didácticas ya permite generar una planificación para el docente o apuntes para el alumnado a partir de tus materiales. Las demás secciones punteadas siguen abiertas a tus sugerencias. Puedes repetir este tutorial desde Ajustes.": "在「创建」中，「教学单元」现已支持根据你的材料为教师生成教案或为学生生成讲义。其余虚线标记的部分仍欢迎你的建议。你可以从「设置」中重播本教程。",
