  "Esta entrada todavía no existe": "此条目尚不存在",
  "Crear la entrada «{name}»": "创建条目「{name}」",
  "Los artículos son para lo que no es un personaje, un lugar ni una facción: la magia, una religión, una lengua, una criatura, un objeto. Todo lo demás ya está en la enciclopedia por sí solo.": "文章用于角色、地点或派系之外的内容：魔法、宗教、语言、生物、物品。其余内容已自动收录在百科中。",
  "Nuevo artículo": "新建文章",
  "Todavía nadie ha definido esto. Al crearlo, todas las menciones que lo esperaban quedarán enlazadas.": "还没有人定义过它。创建后，所有等待它的提及都会建立链接。",
  "Escribe [[ para enlazar con cualquier cosa del mundo": "输入 [[ 即可链接世界中的任何内容",
  "Escribe la entrada…": "输入条目内容…",
