  "Eliminar la entrada": "删除条目",
  "Escribiendo…": "正在写入…",
  "Esta ficha aún no tiene texto. Se escribe en su propia sección.": "此档案还没有文本。可在其专属部分中撰写。",
  "Ficha completa": "完整档案",
  "Las menciones que la enlazaban no se borran: quedarán marcadas como pendientes.": "链接到它的提及不会被删除：它们会被标记为待处理。",
  "Mencionada en": "提及于",
  "No hay bastante material todavía: escribe un resumen o enlaza algo.": "材料还不够：请撰写摘要或链接一些内容。",
