  "Todavía no hay nada escrito aquí.": "这里还没有任何内容。",
  "Buscar en todo el mundo…": "搜索整个世界…",
  "Buscar «{query}» en el texto completo": "在全文中搜索「{query}」",
  "Con texto": "有文本",
