  "Tipo de entrada": "条目类型",
  "{count} en el texto completo": "全文中{count}处",
  "«{query}» no aparece en ningún texto del mundo.": "「{query}」未出现在世界中的任何文本里。",
  "reglas del mundo, conflictos, arcos narrativos, consistencia, preguntas abiertas, tramas y manuscritos": "世界规则、冲突、叙事弧线、一致性、开放问题、情节与手稿",
  "En la enciclopedia": "在百科中",
  "{count} sin desarrollar": "{count}项未展开",
  "Construye un mundo de ficción pieza a pieza: personajes, lugares, facciones, culturas, escenas y mapas. La enciclopedia los reúne todos en un solo índice y te deja escribir el resto del mundo —la magia, una religión, una lengua— enlazándolo con [[dobles corchetes]].": "一步步构建虚构世界：角色、地点、派系、文化、场景和地图。百科将它们汇集为一个索引，并让你撰写世界的其余部分——魔法、宗教、语言——用 [[双方括号]] 将其链接起来。",
  "Analizar el mundo": "分析世界",
  "Aparecen a menudo y no están definidos": "频繁出现但尚未定义",
  "Esto es una sospecha, no un hecho: son nombres que se repiten en tus textos.": "这只是猜测，并非事实：它们是你的文本中反复出现的名称。",
  "Lo escribiste tú entre dobles corchetes, así que ya existen en tu mundo.": "这些是你用双方括号写下的，因此它们已存在于你的世界中。",
  "Lo que falta por definir": "尚待定义",
  "Los enlazaste y no existen": "你链接了它们，但它们不存在",
  "Nada pendiente: todo lo que el mundo nombra tiene entrada.": "没有待处理项：世界提到的所有内容都有条目。",
  "«{name}» creada y enlazada.": "「{name}」已创建并链接。",
