  "Escribe primero qué es lo que no has decidido: «???» a secas no da para responder.": "先写下你尚未决定的内容：光写「???」无法作答。",
  "Proponer respuestas": "提出答案",
  "Solo el enunciado. El precio y los límites los escribes tú: cada uno responde a una pregunta distinta.": "只写陈述。代价和限制由你来写：各自回答不同的问题。",
  "Todavía no hay de dónde escribirla: dime sobre qué rige, empieza una línea o márcala en una escena.": "还没有可依据的内容来写它：告诉我它管辖什么，起一行开头，或在场景中标记。",
  "Ha mirado": "已查看",
  "No escribe nada en tu mundo: lo que te proponga, lo copias tú o lo conviertes en pregunta abierta.": "它不会写入你的世界：它提出的任何内容，你自行复制或将其转为开放问题。",
  "No he encontrado nada de tu mundo en esa pregunta. Nombra un personaje, un lugar, una escena o una ley y vuelvo a mirar.": "我在那个问题里没有找到任何属于你的世界的内容。说出一个角色、一个地点、一个场景或一条法则，我再看一遍。",
  "Nodus calcula y el modelo redacta: responde con lo que hay en tus fichas, y cita.": "Nodus 负责计算，模型负责撰写：它依据你的卡片内容作答，并给出引注。",
  "Pregúntale a tu mundo. Nombra en la pregunta lo que quieras que mire.": "向你的世界提问。在问题里点名你想让它查看的内容。",
  "Seguir con esto": "继续这个",
