  "El capítulo va de aquí a la siguiente marca. Para moverlo, mueve sus escenas.": "本章从这里延伸到下一个标记。要移动它，就移动它的场景。",
  "El manuscrito de la escena enlaza a alguien que no está en su reparto, así que ni la cronología ni los viajes lo tienen en cuenta.": "场景的手稿链接到了不在其出场人物中的人，因此时间线和行程都不把他计入其中。",
  "El manuscrito son tus escenas en orden de relato. Crea la primera en Escenas y aquí la escribes.": "手稿就是按叙事顺序排列的场景。在「场景」中创建第一个，然后在这里撰写。",
