  "Chromium borra las cookies por dominio registrable: al borrar las de un subdominio se borran también las del dominio principal y sus demás subdominios.": "Chromium 按可注册域删除 Cookie：删除某个子域的 Cookie 时，也会删除主域及其其他子域的 Cookie。",
  "Nodus puede medir la caché y el tamaño total del perfil. Chromium no informa del tamaño de cada categoría de almacenamiento por separado, así que las demás se muestran por número de sitios afectados.": "Nodus 可以测量缓存和配置文件总大小。Chromium 不会单独报告各存储类别的大小，因此其余类别按受影响的网站数量显示。",
  "Nodus Browser conserva cookies y almacenamiento de sitio para que sigas con la sesión iniciada donde corresponda. Nodus no guarda usuarios ni contraseñas, y no incluye gestor de contraseñas.": "Nodus Browser 保留 Cookie 和网站存储，以便你在相应网站保持登录。Nodus 不保存用户名和密码，也不包含密码管理器。",
