  "El Espacio de trabajo reúne notas, borradores y organización en una única superficie. Conserva las citas clicables y permite estructurar el manuscrito sin separar artificialmente Escritura y Proyectos.": "工作空间将笔记、草稿和组织汇集于同一界面。它保留可点击的引注，并让你组织手稿，而无需人为地分隔写作与项目。",
