  "Modelos escritos a mano": "手动输入的模型",
  "Si tu servidor no publica catálogo, escribe aquí los identificadores. Quedan guardados y se pueden elegir en cualquier selector de modelo.": "如果你的服务器没有提供目录，请在此处输入标识符。它们会被保存，并可在任何模型选择器中选用。",
