  "Actualización {version} lista. Puedes instalarla y reiniciar cuando quieras.": "更新{version}已就绪。你可以随时安装并重启。",
  "Puedes seguir trabajando. Nodus solo se reiniciará cuando elijas instalar la actualización.": "你可以继续工作。只有在你选择安装更新时，Nodus才会重启。",
